C_BG       = Color3.fromRGB(5, 4, 10)
C_HEADER   = Color3.fromRGB(10, 5, 12)
C_CARD     = Color3.fromRGB(15, 8, 14)
C_CARD_HOV = Color3.fromRGB(37, 13, 28)
C_BORDER   = Color3.fromRGB(139, 58, 101)
C_HIGHLIGHT      = Color3.fromRGB(226, 104, 169)
C_SHADE  = Color3.fromRGB(112, 35, 74)
C_HIGHLIGHT_BRIGHT = Color3.fromRGB(255, 218, 237)
C_WHITE    = Color3.fromRGB(255, 247, 251)
C_GREY     = Color3.fromRGB(194, 164, 180)
C_DIM      = Color3.fromRGB(48, 22, 36)
C_ACCENT   = Color3.fromRGB(218, 70, 146)
C_SEPARATOR_GRAY = Color3.fromRGB(119, 57, 88)
C_CARD_ACTIVE_BG = Color3.fromRGB(39, 13, 29)

PANEL_W  = 520
PANEL_H  = 860
HEADER_H = 82
TABBAR_H = 48

-- ── Scrolling page factory ────────────────────────────────────────────────
local function buildGui_createScrollingPages(parent)
    local pages = {}
    for _, n in ipairs({"Speed","Main","Move","Config","Keybinds"}) do
        local sf = Instance.new("ScrollingFrame", parent)
        sf.Size = UDim2.new(1,0,1,0)
        sf.BackgroundTransparency = 1
        sf.BorderSizePixel = 0
        sf.ScrollBarThickness = 3
        sf.ScrollBarImageColor3 = C_HIGHLIGHT
        sf.Visible = false
        sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
        sf.CanvasSize = UDim2.new(0,0,0,0)
        pcall(function() sf.ElasticBehavior = Enum.ElasticBehavior.Always end)
        pcall(function() sf.ScrollingDirection = Enum.ScrollingDirection.Y end)
        local ll = Instance.new("UIListLayout", sf)
        ll.SortOrder = Enum.SortOrder.LayoutOrder
        ll.Padding = UDim.new(0,4)
        ll.FillDirection = Enum.FillDirection.Vertical
        local pp = Instance.new("UIPadding", sf)
        pp.PaddingLeft  = UDim.new(0,10)
        pp.PaddingRight = UDim.new(0,10)
        pp.PaddingTop   = UDim.new(0,8)
        pp.PaddingBottom= UDim.new(0,18)
        pages[n] = sf
    end
    return pages
end

rowCounts = {Speed=0, Main=0, Move=0, Config=0, Keybinds=0}

-- ── Card row ──────────────────────────────────────────────────────────────
local function mkCard(pg, pages, h)
    rowCounts[pg] = rowCounts[pg] + 1
    local f = Instance.new("Frame", pages[pg])
    f.Size = UDim2.new(1,0,0,h or 38)
    f.BackgroundColor3 = C_CARD
    f.BackgroundTransparency = 0.15
    f.BorderSizePixel = 0
    f.LayoutOrder = rowCounts[pg]
    Instance.new("UICorner", f).CornerRadius = UDim.new(0,12)
    local stroke = Instance.new("UIStroke", f)
    stroke.Color = C_BORDER; stroke.Thickness = 1; stroke.Transparency = 0.3
    -- Subtle inner glow gradient
    local cardGrad = Instance.new("UIGradient", f)
    cardGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(20, 20, 20)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(10, 10, 10)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(14, 14, 14)),
    })
    cardGrad.Rotation = 135
    return f
end

-- ── Section divider ───────────────────────────────────────────────────────
local function mkSection(pg, pages, text)
    rowCounts[pg] = rowCounts[pg] + 1
    local f = Instance.new("Frame", pages[pg])
    f.Name = "Section_" .. tostring(text):gsub("[^%w]+", "_")
    f:SetAttribute("XypherSectionTitle", text)
    f.Size = UDim2.new(1,0,0,20)
    f.BackgroundTransparency = 1
    f.BorderSizePixel = 0
    f.LayoutOrder = rowCounts[pg]
    local lbl = Instance.new("TextLabel", f)
    lbl.Size = UDim2.new(1,-10,1,0)
    lbl.Position = UDim2.new(0,10,0,0)
    lbl.BackgroundTransparency = 1
    lbl.Text = text:upper()
    lbl.TextColor3 = C_HIGHLIGHT
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 9
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    local line = Instance.new("Frame", f)
    line.Size = UDim2.new(1,-10,0,1)
    line.Position = UDim2.new(0,10,1,-1)
    line.BackgroundColor3 = C_SEPARATOR_GRAY
    line.BackgroundTransparency = 0.72
    line.BorderSizePixel = 0
end

-- ── Toggle row ────────────────────────────────────────────────────────────
-- Lightweight, fail-safe Halloween cobweb accent for toggle rows.
-- This decoration is deliberately isolated from GUI construction so any
-- decorative failure can never prevent the Vision interface from appearing.
local toggleWebCounter = 0
local function addToggleHalloweenWeb(card)
    if not card or not card.Parent or card:FindFirstChild("HalloweenToggleCobweb") then return end
    local ok = pcall(function()
        toggleWebCounter += 1
        local size = math.random(16, 20)
        local x = math.random(164, 181)
        local y = math.random(7, 11)
        local orientation = math.random(0, 3)
        local alpha = math.random(50, 66) / 100

        local root = Instance.new("Frame")
        root.Name = "HalloweenToggleCobweb"
        root.Position = UDim2.fromOffset(x, y)
        root.Size = UDim2.fromOffset(size, size)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.ZIndex = 2
        root.Active = false
        root.Selectable = false
        root.ClipsDescendants = true
        root.Parent = card

        local strand = Color3.fromRGB(150, 150, 150)
        local highlight = Color3.fromRGB(202, 202, 202)
        local function transform(px, py)
            if orientation == 1 then return size - px, py end
            if orientation == 2 then return size - px, size - py end
            if orientation == 3 then return px, size - py end
            return px, py
        end
        local function webLine(x1, y1, x2, y2, thick, color, transparency, name)
            x1, y1 = transform(x1, y1)
            x2, y2 = transform(x2, y2)
            local dx, dy = x2 - x1, y2 - y1
            local length = math.sqrt(dx * dx + dy * dy)
            if length < 1 then return end
            local f = Instance.new("Frame")
            f.Name = name
            f.AnchorPoint = Vector2.new(0.5, 0.5)
            f.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
            f.Size = UDim2.fromOffset(length, thick)
            f.Rotation = math.deg(math.atan2(dy, dx))
            f.BackgroundColor3 = color
            f.BackgroundTransparency = transparency
            f.BorderSizePixel = 0
            f.ZIndex = 3
            f.Active = false
            f.Selectable = false
            f.Parent = root
        end

        -- Small corner-web silhouette: 3 rays + 2 curved-looking cross bands (7 lines total).
        local edgePoints = {
            {x = size, y = 0},
            {x = size, y = size},
            {x = 0, y = size},
        }
        for i, point in ipairs(edgePoints) do
            webLine(0, 0, point.x, point.y, i == 2 and 1.0 or 0.8, strand, alpha, "ToggleRadialSilk" .. tostring(i))
        end
        for ringIndex, fraction in ipairs({0.42, 0.76}) do
            local p1 = {x = edgePoints[1].x * fraction, y = edgePoints[1].y * fraction}
            local p2 = {x = edgePoints[2].x * fraction, y = edgePoints[2].y * fraction}
            local p3 = {x = edgePoints[3].x * fraction, y = edgePoints[3].y * fraction}
            local color = ringIndex == 2 and highlight or strand
            local transparency = math.min(0.82, alpha + 0.08)
            webLine(p1.x, p1.y, p2.x, p2.y, ringIndex == 2 and 0.9 or 0.75, color, transparency, "ToggleCrossSilk" .. tostring(ringIndex) .. "A")
            webLine(p2.x, p2.y, p3.x, p3.y, ringIndex == 2 and 0.9 or 0.75, color, transparency, "ToggleCrossSilk" .. tostring(ringIndex) .. "B")
        end
        local knot = Instance.new("Frame")
        knot.Name = "ToggleSilkKnot"
        knot.AnchorPoint = Vector2.new(0.5, 0.5)
        local kx, ky = transform(0, 0)
        knot.Position = UDim2.fromOffset(kx, ky)
        knot.Size = UDim2.fromOffset(2, 2)
        knot.BackgroundColor3 = highlight
        knot.BackgroundTransparency = 0.2
        knot.BorderSizePixel = 0
        knot.ZIndex = 4
        knot.Active = false
        knot.Selectable = false
        knot.Parent = root
        Instance.new("UICorner", knot).CornerRadius = UDim.new(1, 0)
    end)
    return ok
end

local toggleWebQueue = {}
local toggleWebQueueHead, toggleWebQueueTail = 1, 0
local toggleWebWorkerRunning = false
local function queueToggleHalloweenWeb(card)
    if not card or not card.Parent then return end
    toggleWebQueueTail += 1
    toggleWebQueue[toggleWebQueueTail] = card
    if toggleWebWorkerRunning then return end
    toggleWebWorkerRunning = true
    task.spawn(function()
        local batch = 0
        while toggleWebQueueHead <= toggleWebQueueTail do
            local target = toggleWebQueue[toggleWebQueueHead]
            toggleWebQueue[toggleWebQueueHead] = nil
            toggleWebQueueHead += 1
            if target and target.Parent then pcall(addToggleHalloweenWeb, target) end
            batch += 1
            if batch >= 4 then
                batch = 0
                task.wait()
            end
        end
        toggleWebQueue = {}
        toggleWebQueueHead, toggleWebQueueTail = 1, 0
        toggleWebWorkerRunning = false
    end)
end

local function mkToggle(pg, pages, label, defKey, defOn, onToggle, onKeyChanged, previewImageId)
    -- Consistent row height and control spacing make touch targets easier to use.
    local card = mkCard(pg, pages, 42)
    card.Name = "ToggleRow_" .. tostring(label):gsub("[^%w]+", "_")
    local isCrosshairToggle = tostring(label):lower():find("crosshair", 1, true) ~= nil
    -- Give every toggle row enough contrast for all labels, including on image backgrounds.
    -- Keep a mild glass effect while avoiding the very high transparency that hid text.
    card.BackgroundTransparency = isCrosshairToggle and 0.08 or 0.24
    local cardStroke = card:FindFirstChildOfClass("UIStroke")
    local hasPreview = type(previewImageId) == "string" and (previewImageId:match("^%d+$") ~= nil or (previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_5 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_6 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_7))
    local switchRightInset = defKey and 70 or 14
    local switchWidth = 42
    local previewWidth = 38
    local labelRightReserve = switchRightInset + switchWidth + 10
    if hasPreview then labelRightReserve = labelRightReserve + previewWidth + 8 end

    -- Draw the decorative web after the row is created; it must never block
    -- creation of the actual toggle or the rest of the Vision GUI.
    -- Keep feature cards clean and reference-matched; no decorative layer may cover controls.

    local lbl = Instance.new("TextLabel", card)
    lbl.Name = "ToggleLabel"
    lbl.Size = UDim2.new(1, -(12 + labelRightReserve), 1, 0)
    lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1
    lbl.Text = tostring(label)
    -- Apply one high-contrast style to every toggle label, not only crosshair rows.
    -- A solid white face, strong black outline and responsive sizing keep labels
    -- legible over all themes and custom background images.
    lbl.TextTransparency = 0
    lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    lbl.TextStrokeTransparency = 0.04
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextSize = 14
    lbl.TextScaled = true
    lbl.TextWrapped = false
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.ZIndex = 6
    local toggleLabelSize = Instance.new("UITextSizeConstraint")
    toggleLabelSize.Name = "ToggleLabelSizeConstraint"
    toggleLabelSize.MinTextSize = 11
    toggleLabelSize.MaxTextSize = 14
    toggleLabelSize.Parent = lbl
    pcall(function() lbl.TextTruncate = Enum.TextTruncate.AtEnd end)

    -- Optional non-interactive thumbnail preview for mobile-button Background rows.
    -- It is placed between the label and switch, above the transparent click area.
    if hasPreview then
        local previewFrame = Instance.new("Frame")
        previewFrame.Name = "BackgroundPreviewFrame"
        previewFrame.AnchorPoint = Vector2.new(1, 0.5)
        previewFrame.Position = UDim2.new(1, -(switchRightInset + switchWidth + 8), 0.5, 0)
        previewFrame.Size = UDim2.fromOffset(previewWidth, 24)
        previewFrame.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
        previewFrame.BackgroundTransparency = 0.05
        previewFrame.BorderSizePixel = 0
        previewFrame.ClipsDescendants = true
        previewFrame.Active = false
        previewFrame.Selectable = false
        previewFrame.ZIndex = 10
        previewFrame.Visible = true
        previewFrame.Parent = card
        Instance.new("UICorner", previewFrame).CornerRadius = UDim.new(0, 6)

        local previewStroke = Instance.new("UIStroke")
        previewStroke.Name = "PreviewNeonBorder"
        previewStroke.Color = Color3.fromRGB(157, 157, 157)
        previewStroke.Thickness = 1
        previewStroke.Transparency = 0.22
        previewStroke.Parent = previewFrame

        local previewImage = Instance.new("ImageLabel")
        previewImage.Name = "BackgroundPreviewImage"
        previewImage.Size = UDim2.new(1, -2, 1, -2)
        previewImage.Position = UDim2.fromOffset(1, 1)
        previewImage.BackgroundTransparency = 1
        previewImage.BorderSizePixel = 0
        if previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_5 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_6 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_7 then
            -- The asynchronous resolver below fills this preview without blocking startup.
            previewImage.Image = ""
        else
            previewImage.Image = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=150&h=100"
        end
        previewImage.ImageTransparency = 0
        previewImage.ScaleType = Enum.ScaleType.Crop
        previewImage.Active = false
        previewImage.Selectable = false
        previewImage.ZIndex = 11
        previewImage.Visible = true
        previewImage.Parent = previewFrame
        Instance.new("UICorner", previewImage).CornerRadius = UDim.new(0, 5)

        -- Resolve thumbnails asynchronously with fallbacks; never block UI creation.
        -- Some image assets resolve through rbxthumb, while others require rbxassetid.
        task.spawn(function()
            if previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_5 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_6 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_7 then
                local localUri = ensureXypherUploadedPhotoAsset(previewImageId)
                if localUri and previewImage.Parent then previewImage.Image = localUri end
                return
            end
            local thumbnailUri = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=150&h=100"
            local directUri = "rbxassetid://" .. previewImageId
            local largeThumbnailUri = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=420&h=420"
            local function waitLoaded(timeout)
                local deadline = os.clock() + timeout
                while os.clock() < deadline and previewImage.Parent do
                    local okLoaded, isLoaded = pcall(function() return previewImage.IsLoaded end)
                    if okLoaded and isLoaded then return true end
                    task.wait(0.1)
                end
                return false
            end
            if waitLoaded(2.0) then return end
            if not previewImage.Parent then return end
            pcall(function() previewImage.Image = directUri end)
            if waitLoaded(2.0) then return end
            if not previewImage.Parent then return end
            pcall(function() previewImage.Image = largeThumbnailUri end)
            waitLoaded(1.5)
        end)
    end

    local keyBtn = nil
    if defKey then
        keyBtn = Instance.new("TextButton", card)
        keyBtn.Name = "ToggleKeybind"
        keyBtn.AnchorPoint = Vector2.new(1, 0.5)
        keyBtn.Size = UDim2.fromOffset(48, 26)
        keyBtn.Position = UDim2.new(1, -8, 0.5, 0)
        keyBtn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        keyBtn.BackgroundTransparency = 0
        keyBtn.BorderSizePixel = 0
        keyBtn.ZIndex = 10
        keyBtn.Text = (defKey or Enum.KeyCode.Unknown).Name
        keyBtn.TextTransparency = 0
        keyBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        keyBtn.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        keyBtn.TextStrokeTransparency = 0.08
        keyBtn.Font = Enum.Font.GothamBlack
        keyBtn.TextSize = 11
        keyBtn.TextScaled = true
        local keyTextLimit = Instance.new("UITextSizeConstraint")
        keyTextLimit.MinTextSize = 8
        keyTextLimit.MaxTextSize = 11
        keyTextLimit.Parent = keyBtn
        Instance.new("UICorner", keyBtn).CornerRadius = UDim.new(0,8)
        local ks = Instance.new("UIStroke", keyBtn)
        ks.Color = Color3.fromRGB(35, 35, 35)
        ks.Thickness = 1
        ks.Transparency = 0.52
        ks.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        local listening = false
        keyBtn.MouseButton1Click:Connect(function()
            if listening then return end; listening = true
            local prev = keyBtn.Text; keyBtn.Text = "···"; keyBtn.TextColor3 = C_HIGHLIGHT
            local conn
            conn = UIS.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.Keyboard or inp.UserInputType == Enum.UserInputType.Gamepad1 then
                    if inp.KeyCode ~= Enum.KeyCode.Escape then
                        keyBtn.Text = inp.KeyCode.Name; keyBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                        if onKeyChanged then onKeyChanged(inp.KeyCode, inp.UserInputType == Enum.UserInputType.Gamepad1) end
                    else keyBtn.Text = prev; keyBtn.TextColor3 = Color3.fromRGB(255, 255, 255) end
                    listening = false; conn:Disconnect()
                end
            end)
        end)
    end

    -- Refined Halloween accent shared by every toggle row.
    local activeAccent = Instance.new("Frame", card)
    activeAccent.Name = "HalloweenToggleAccent"
    activeAccent.AnchorPoint = Vector2.new(0, 0.5)
    activeAccent.Position = UDim2.new(0, 0, 0.5, 0)
    activeAccent.Size = UDim2.new(0, 3, 0, 13)
    activeAccent.BackgroundColor3 = C_HIGHLIGHT
    activeAccent.BackgroundTransparency = 0.78
    activeAccent.BorderSizePixel = 0
    activeAccent.ZIndex = 4
    activeAccent.Active = false
    activeAccent.Selectable = false
    Instance.new("UICorner", activeAccent).CornerRadius = UDim.new(1, 0)
    local activeAccentGradient = Instance.new("UIGradient", activeAccent)
    activeAccentGradient.Rotation = 90
    activeAccentGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
        ColorSequenceKeypoint.new(0.5, C_HIGHLIGHT),
        ColorSequenceKeypoint.new(1, C_SHADE),
    })

    -- Toggle premium: dark when OFF, neon accent when ON.
    local pillBg = Instance.new("Frame", card)
    pillBg.Name = "ToggleTrack"
    pillBg.Size = UDim2.fromOffset(switchWidth, 24)
    pillBg.AnchorPoint = Vector2.new(1, 0.5)
    pillBg.Position = UDim2.new(1, -switchRightInset, 0.5, 0)
    pillBg.BackgroundColor3 = Color3.fromRGB(9, 9, 9)
    pillBg.BackgroundTransparency = 0
    pillBg.BorderSizePixel = 0
    pillBg.ZIndex = 6
    pillBg.ClipsDescendants = false
    Instance.new("UICorner", pillBg).CornerRadius = UDim.new(1,0)
    local pillStroke = Instance.new("UIStroke", pillBg)
    pillStroke.Name = "TrackStroke"
    pillStroke.Color = Color3.fromRGB(151, 151, 151)
    pillStroke.Thickness = 0.8
    pillStroke.Transparency = 0.62
    local pillGradient = Instance.new("UIGradient", pillBg)
    pillGradient.Name = "TrackGradient"
    pillGradient.Rotation = 90
    pillGradient.Enabled = true
    pillGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(30, 30, 30)),
        ColorSequenceKeypoint.new(0.55, Color3.fromRGB(15, 15, 15)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(7, 7, 7)),
    })
    local dotBack = Instance.new("Frame", pillBg)
    dotBack.Name = "DotBack"
    dotBack.AnchorPoint = Vector2.new(0.5,0.5)
    dotBack.Position = UDim2.new(0.5,0,0.5,1)
    dotBack.Size = UDim2.fromOffset(16, 16)
    dotBack.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    dotBack.BackgroundTransparency = isCrosshairToggle and 0.28 or 0.55
    dotBack.BorderSizePixel = 0
    dotBack.ZIndex = 6
    Instance.new("UICorner", dotBack).CornerRadius = UDim.new(1,0)
    local dot = Instance.new("Frame", pillBg)
    dot.Name = "Knob"
    dot.AnchorPoint = Vector2.new(0.5,0.5)
    dot.Position = UDim2.new(0.5,0,0.5,0)
    dot.Size = UDim2.fromOffset(14, 14)
    dot.BackgroundColor3 = Color3.fromRGB(93, 93, 93)
    dot.BorderSizePixel = 0
    dot.ZIndex = 7
    Instance.new("UICorner", dot).CornerRadius = UDim.new(1,0)
    local dotGradient = Instance.new("UIGradient", dot)
    dotGradient.Name = "VisionDotGradient"
    dotGradient.Rotation = 90
    dotGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(235, 235, 235)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(128, 128, 128)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(49, 49, 49)),
    })
    local dotGloss = Instance.new("Frame", dot)
    dotGloss.Name = "VisionOrangeGloss"
    dotGloss.Size = UDim2.new(0.46,0,0.24,0)
    dotGloss.Position = UDim2.new(0.22,0,0.11,0)
    dotGloss.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    dotGloss.BackgroundTransparency = 0.62
    dotGloss.BorderSizePixel = 0
    dotGloss.ZIndex = 8
    Instance.new("UICorner", dotGloss).CornerRadius = UDim.new(1,0)
    local dotScale = Instance.new("UIScale", dot)
    dotScale.Scale = 1

    local isOn = defOn or false
    local function setV(on)
        isOn = on
        local fadeInfo = TweenInfo.new(0.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
        local dotColor = on and C_HIGHLIGHT or (isCrosshairToggle and Color3.fromRGB(155, 155, 155) or Color3.fromRGB(93, 93, 93))
        local dotSequence = on and ColorSequence.new({
            ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
            ColorSequenceKeypoint.new(0.46, C_HIGHLIGHT),
            ColorSequenceKeypoint.new(1, C_SHADE),
        }) or (isCrosshairToggle and ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(250, 250, 250)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(180, 180, 180)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(105, 105, 105)),
        }) or ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(235, 235, 235)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(128, 128, 128)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(49, 49, 49)),
        }))
        TS_G:Create(dot, fadeInfo, {BackgroundColor3 = dotColor}):Play()
        dotGradient.Color = dotSequence
        TS_G:Create(dotScale, TweenInfo.new(0.28,Enum.EasingStyle.Back,Enum.EasingDirection.Out), {
            Scale = on and 1.08 or 0.92,
        }):Play()
        task.delay(0.02, function()
            if dotScale and dotScale.Parent then
                TS_G:Create(dotScale, TweenInfo.new(0.28,Enum.EasingStyle.Back,Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
        end)
        dotGloss.BackgroundTransparency = on and 0.44 or 0.62

        -- Keep the activation switch itself fully opaque; transparency applies to
        -- the row surface only, never to the control the player must tap.
        pillBg.BackgroundTransparency = 0
        pillGradient.Enabled = true
        pillGradient.Color = on and ColorSequence.new({
            ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
            ColorSequenceKeypoint.new(0.42, C_HIGHLIGHT),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(8, 5, 18)),
        }) or ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(33, 33, 33)),
            ColorSequenceKeypoint.new(0.55, Color3.fromRGB(16, 16, 16)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(7, 7, 7)),
        })
        pillStroke.Color = on and C_HIGHLIGHT or C_DIM
        TS_G:Create(pillStroke, fadeInfo, {
            Thickness = on and (isCrosshairToggle and 1.6 or 1.25) or (isCrosshairToggle and 1.05 or 0.6),
            Transparency = on and (isCrosshairToggle and 0.06 or 0.18) or (isCrosshairToggle and 0.24 or 0.58),
        }):Play()
        TS_G:Create(activeAccent, fadeInfo, {
            BackgroundTransparency = on and 0.03 or 0.78,
            Size = on and UDim2.new(0, 3, 0, 28) or UDim2.new(0, 3, 0, 15),
        }):Play()
        card.BackgroundColor3 = on and C_CARD_ACTIVE_BG or C_CARD
        if cardStroke then
            TS_G:Create(cardStroke, fadeInfo, {
                Color = on and (isCrosshairToggle and C_HIGHLIGHT or C_SEPARATOR_GRAY) or C_BORDER,
                Transparency = on and (isCrosshairToggle and 0.10 or 0.42) or (isCrosshairToggle and 0.12 or 0.3),
                Thickness = on and (isCrosshairToggle and 1.5 or 1.15) or 1,
            }):Play()
        end
    end

    local clickArea = Instance.new("TextButton", card)
    clickArea.Name = "ToggleClickArea"
    clickArea.Size = UDim2.new(1,0,1,0)
    clickArea.BackgroundTransparency = 1
    clickArea.Text = ""
    clickArea.AutoButtonColor = false
    clickArea.Active = true
    clickArea.ClipsDescendants = true
    clickArea.ZIndex = 5

    -- Touch/click feedback: a small accent ripple expands and fades inside the row.
    -- It is non-interactive and clipped to the toggle card so it cannot cover nearby controls.
    local function playToggleClickRipple(inputObject)
        pcall(function()
            if not clickArea.Parent then return end
            local size = clickArea.AbsoluteSize
            local px, py = size.X * 0.5, size.Y * 0.5
            if inputObject and inputObject.Position then
                local origin = clickArea.AbsolutePosition
                px = math.clamp(inputObject.Position.X - origin.X, 0, size.X)
                py = math.clamp(inputObject.Position.Y - origin.Y, 0, size.Y)
            end
            local diameter = math.clamp(math.min(size.X, 46), 28, 46)
            local ripple = Instance.new("Frame")
            ripple.Name = "ToggleClickRipple"
            ripple.AnchorPoint = Vector2.new(0.5, 0.5)
            ripple.Position = UDim2.fromOffset(px, py)
            ripple.Size = UDim2.fromOffset(0, 0)
            ripple.BackgroundColor3 = C_HIGHLIGHT_BRIGHT
            ripple.BackgroundTransparency = 0.72
            ripple.BorderSizePixel = 0
            ripple.Active = false
            ripple.Selectable = false
            ripple.ZIndex = 5
            ripple.Parent = clickArea
            Instance.new("UICorner", ripple).CornerRadius = UDim.new(1, 0)
            local rippleStroke = Instance.new("UIStroke")
            rippleStroke.Color = C_HIGHLIGHT
            rippleStroke.Thickness = 1.1
            rippleStroke.Transparency = 0.32
            rippleStroke.Parent = ripple

            local expandTween = TS_G:Create(ripple, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.fromOffset(diameter, diameter),
                BackgroundTransparency = 1,
            })
            local fadeStrokeTween = TS_G:Create(rippleStroke, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Transparency = 1,
                Thickness = 0.5,
            })
            expandTween:Play()
            fadeStrokeTween:Play()
            expandTween.Completed:Connect(function()
                if ripple and ripple.Parent then ripple:Destroy() end
            end)
        end)
    end

    clickArea.Activated:Connect(function(inputObject)
        playToggleClickRipple(inputObject)
        isOn = not isOn
        setV(isOn)
        if onToggle then onToggle(isOn) end
    end)
    clickArea.MouseEnter:Connect(function()
        TS_G:Create(card, TweenInfo.new(0.12), {BackgroundColor3 = C_CARD_HOV}):Play()
    end)
    clickArea.MouseLeave:Connect(function()
        TS_G:Create(card, TweenInfo.new(0.15), {
            BackgroundColor3 = isOn and C_CARD_ACTIVE_BG or C_CARD
        }):Play()
    end)

    setV(isOn)
    return setV, keyBtn, card
end

-- ── Number input row ──────────────────────────────────────────────────────
local function mkInput(pg, pages, label, default, onChange)
    local card = mkCard(pg, pages, 36)
    local lbl = Instance.new("TextLabel", card)
    lbl.Size = UDim2.new(0.55,-8,1,0); lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1; lbl.Text = label
    lbl.TextColor3 = C_WHITE; lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 11; lbl.TextXAlignment = Enum.TextXAlignment.Left
    local box = Instance.new("TextBox", card)
    box.Size = UDim2.new(0,66,0,26); box.Position = UDim2.new(1,-74,0.5,-13)
    box.BackgroundColor3 = Color3.fromRGB(18, 18, 18); box.BorderSizePixel = 0
    box.Text = tostring(default); box.TextColor3 = C_WHITE
    box.Font = Enum.Font.GothamBlack; box.TextSize = 11
    box.ClearTextOnFocus = false; box.MultiLine = false
    pcall(function() box.ReturnKeyType = Enum.ReturnKeyType.Done end)
    Instance.new("UICorner", box).CornerRadius = UDim.new(0,8)
    local boxStroke = Instance.new("UIStroke", box)
    boxStroke.Color = C_BORDER; boxStroke.Thickness = 0.8
    local lastVal = tostring(default); local isFocused = false
    box.Focused:Connect(function()
        isFocused = true
        TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_HIGHLIGHT}):Play()
    end)
    local function applyVal()
        if not isFocused then return end
        isFocused = false
        TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_BORDER}):Play()
        local n = tonumber(box.Text)
        if n then lastVal = tostring(n); box.Text = lastVal; onChange(n)
        else box.Text = lastVal end
        pcall(function() box:ReleaseFocus(false) end)
    end
    box.FocusLost:Connect(function()
        if isFocused then
            isFocused = false
            TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_BORDER}):Play()
            local n = tonumber(box.Text)
            if n then lastVal = tostring(n); box.Text = lastVal; onChange(n)
            else box.Text = lastVal end
        end
    end)
    pcall(function() box.ReturnPressedFromOnScreenKeyboard:Connect(applyVal) end)
    UIS.TouchTap:Connect(function(positions)
        if not isFocused then return end
        pcall(function()
            local abs = box.AbsolutePosition; local sz = box.AbsoluteSize; local tp = positions[1]
            if tp and not (tp.X>=abs.X and tp.X<=abs.X+sz.X and tp.Y>=abs.Y and tp.Y<=abs.Y+sz.Y) then
                applyVal()
            end
        end)
    end)
    return box
end

-- ── Action / keybind row ──────────────────────────────────────────────────
local function mkActionRow(pg, pages, labelText, keyEntry, onRun)
    local card = mkCard(pg, pages, 36)
    local lbl = Instance.new("TextLabel", card)
    lbl.Size = UDim2.new(0,180,1,0); lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelText
    lbl.TextColor3 = C_WHITE; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left

    -- Toda la fila ejecuta la acción al tocarla; el botón de tecla sigue permitiendo reasignarla.
    if onRun then
        local actionTap = Instance.new("TextButton", card)
        actionTap.Name = "ActionTapArea"
        actionTap.Size = UDim2.new(1, 0, 1, 0)
        actionTap.BackgroundTransparency = 1
        actionTap.Text = ""
        actionTap.AutoButtonColor = false
        actionTap.Active = true
        actionTap.ZIndex = 2
        actionTap.Activated:Connect(function()
            task.spawn(onRun)
        end)
    end

    if keyEntry then
        local keyBtn = Instance.new("TextButton", card)
        keyBtn.Size = UDim2.new(0,52,0,24); keyBtn.Position = UDim2.new(1,-62,0.5,-12)
        keyBtn.BackgroundColor3 = Color3.fromRGB(18, 18, 18); keyBtn.BorderSizePixel = 0; keyBtn.ZIndex = 10
        keyBtn.Text = (keyEntry.kb or keyEntry.gp or Enum.KeyCode.Unknown).Name
        keyBtn.TextColor3 = C_GREY; keyBtn.Font = Enum.Font.GothamBold; keyBtn.TextSize = 9
        Instance.new("UICorner", keyBtn).CornerRadius = UDim.new(0,7)
        local ks = Instance.new("UIStroke", keyBtn); ks.Color = C_BORDER; ks.Thickness = 0.8
        local listening = false
        keyBtn.MouseButton1Click:Connect(function()
            if listening then return end; listening = true
            local prev = keyBtn.Text; keyBtn.Text = "···"; keyBtn.TextColor3 = C_HIGHLIGHT
            local conn
            conn = UIS.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.Keyboard or inp.UserInputType == Enum.UserInputType.Gamepad1 then
                    if inp.KeyCode ~= Enum.KeyCode.Escape then
                        keyBtn.Text = inp.KeyCode.Name; keyBtn.TextColor3 = C_GREY
                        if inp.UserInputType == Enum.UserInputType.Gamepad1 then
                            keyEntry.gp = inp.KeyCode; keyEntry.kb = nil
                        else keyEntry.kb = inp.KeyCode; keyEntry.gp = nil end
                        saveConfig()
                    else keyBtn.Text = prev; keyBtn.TextColor3 = C_GREY end
                    listening = false; conn:Disconnect()
                end
            end)
        end)
    end
    return function(newLabel)
        if lbl and lbl.Parent then lbl.Text = newLabel end
    end
end

-- ── Mini toggle (minimised button) ────────────────────────────────────────
local function buildGui_createMiniToggle(gui, showGuiFn)
    -- Independent launcher. The direct fallback below is intentional: it can
    -- reopen the stored dashboard even if the original show callback is stale.
    local btn = Instance.new("TextButton")
    btn.Name = "OpenGuiButton"
    btn.Size = UDim2.fromOffset(104, 34)
    btn.Position = UDim2.new(0, 18, 0, 70)
    btn.BackgroundColor3 = Color3.fromRGB(11, 7, 20)
    btn.BackgroundTransparency = 0.02
    btn.BorderSizePixel = 0
    btn.Text = "xypher."
    btn.TextColor3 = C_WHITE
    btn.Font = Enum.Font.GothamBlack
    btn.TextSize = 11
    btn.TextScaled = false
    btn.TextXAlignment = Enum.TextXAlignment.Center
    btn.TextYAlignment = Enum.TextYAlignment.Center
    btn.AutoButtonColor = false
    btn.ZIndex = 10
    btn.Visible = true
    btn.Active = true
    btn.Selectable = true
    btn.Parent = gui
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
    local ms = Instance.new("UIStroke", btn)
    ms.Color = C_HIGHLIGHT
    ms.Thickness = 1.35
    ms.Transparency = 0.12
    local grad = Instance.new("UIGradient", btn)
    grad.Rotation = 12
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(42, 36, 67)),
        ColorSequenceKeypoint.new(0.52, Color3.fromRGB(16, 17, 26)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(48, 38, 71)),
    })
    local titleConstraint = Instance.new("UITextSizeConstraint", btn)
    titleConstraint.MinTextSize = 10
    titleConstraint.MaxTextSize = 13

    local lastActivation = -math.huge
    local function activateMiniOnce()
        local now = os.clock()
        if now - lastActivation < 0.30 then return end
        lastActivation = now

        -- While the interface is still being built, remember the request but
        -- also attempt a direct reopen if the main root has already been created.
        if not S._xypherBuildReady then S._xypherOpenPending = true end

        -- First use the normal transition. The old implementation always ran the
        -- fallback afterward, resetting Scale/Position immediately and cancelling
        -- the visible entrance animation even when showGuiFn had worked correctly.
        local callbackWasRun = type(showGuiFn) == "function"
        local callbackOk, callbackErr = pcall(function()
            if callbackWasRun then showGuiFn() end
        end)
        if not callbackOk then
            warn("[XYPHER] Open GUI transition error: " .. tostring(callbackErr))
        end

        local opened = false
        local root = S.mainMenuFrame
        local screenGui = nil
        if root and root.Parent then
            screenGui = root:FindFirstAncestorOfClass("ScreenGui")
        end

        -- A successful callback owns the animation. Do not reset its scale or
        -- position; only confirm that the real GUI remains enabled and visible.
        if callbackWasRun and callbackOk and root and root.Parent and root.Visible then
            if screenGui and not screenGui.Enabled then screenGui.Enabled = true end
            opened = true
        end

        if not opened then
            if not (root and root.Parent) then
                -- Recover the root from either host if an executor left a stale state ref.
                pcall(function()
                    local core = game:GetService("CoreGui")
                    local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
                    local hosts = {core, pg}
                    for _, host in ipairs(hosts) do
                        if host then
                            local screen = host:FindFirstChild("Vision")
                            local candidate = screen and screen:FindFirstChild("Outer")
                            if candidate and candidate:IsA("GuiObject") and candidate.Parent then
                                root = candidate
                                S.mainMenuFrame = candidate
                                gui = screen
                                screenGui = screen
                                break
                            end
                        end
                    end
                end)
            end
            if root and root.Parent then
                local fallbackOk, fallbackErr = pcall(function()
                    root.AnchorPoint = Vector2.new(0, 0.5)
                    root.Size = UDim2.fromOffset(PANEL_W, PANEL_H)
                    local targetPosition = UDim2.new(0, 8, 0.5, 0)
                    root.Position = UDim2.new(0, 8, 0.5, 30)
                    root.Visible = true

                    local scaleObj = S.mainGuiScaleObj
                    if not (scaleObj and scaleObj.Parent) then
                        scaleObj = root:FindFirstChildWhichIsA("UIScale", true)
                        if scaleObj then S.mainGuiScaleObj = scaleObj end
                    end
                    if scaleObj and scaleObj.Parent then
                        local camera = workspace.CurrentCamera
                        local viewport = camera and camera.ViewportSize or Vector2.new(PANEL_W, PANEL_H)
                        local fit = math.min(1, (viewport.X - 16) / PANEL_W, (viewport.Y - 20) / PANEL_H)
                        if S.IS_TOUCH_DEVICE then fit = math.min(fit, S.phoneGuiScale or 0.72) end
                        local targetScale = math.max(0.24, fit * 0.96)
                        scaleObj.Scale = math.max(0.14, targetScale * 0.58)
                        if S.menuTween then pcall(function() S.menuTween:Cancel() end) end
                        S.menuTween = TS_G:Create(scaleObj, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = targetScale})
                        S.menuTween:Play()
                    end
                    if root.Parent and root.Parent:IsA("ScreenGui") then root.Parent.Enabled = true end
                    if screenGui and screenGui:IsA("ScreenGui") then screenGui.Enabled = true end
                    TS_G:Create(root, TweenInfo.new(0.42, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = targetPosition}):Play()
                    if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
                end)
                opened = fallbackOk
                if not fallbackOk then
                    warn("[XYPHER] Open GUI fallback error: " .. tostring(fallbackErr))
                end
            end
        end

        if opened then
            btn.Visible = false
            S._xypherOpenPending = false
            if type(S._xypherSetGameplayOverlaysVisible) == "function" then
                pcall(S._xypherSetGameplayOverlaysVisible, false)
            end
        else
            -- Do not vanish if the target root is unavailable; leave the user
            -- an actionable launcher rather than a dead end.
            btn.Visible = true
        end
    end

    btn.Activated:Connect(activateMiniOnce)
    btn.MouseButton1Click:Connect(activateMiniOnce)
    btn.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            activateMiniOnce()
        end
    end)
    return btn
end

-- ── Kroblox (ported from Ace Duels) ────────────────────────────────────────
_G._VisionKrobloxMode = _G._VisionKrobloxMode or "Off"
VISION_KROBLOX_ASSETS = {
    ["Left Leg"] = {
        id = "rbxassetid://139607673", targetBodyPart = "LeftUpperLeg",
        partsToHide = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
        scale = Vector3.new(1, 1, 1), audio = "rbxassetid://87998522263554",
        offset = CFrame.new(0, 0, 0) * CFrame.Angles(1.2, 0, 0),
    },
    ["Right Leg"] = {
        id = "rbxassetid://139607718", targetBodyPart = "RightUpperLeg",
        partsToHide = {"RightUpperLeg", "RightLowerLeg", "RightFoot"},
        scale = Vector3.new(1, 1, 1), audio = "rbxassetid://135315310485417",
        offset = CFrame.new(0, 0, 0) * CFrame.Angles(0, 1.2, 0),
    },
}
local function clearVisionKroblox()
    local character = LP.Character
    if not character then return end
    for _, name in ipairs({"Korblox_LeftLeg", "Korblox_RightLeg", "VisionKroblox_LeftLeg", "VisionKroblox_RightLeg"}) do
        local object = character:FindFirstChild(name)
        if object then pcall(function() object:Destroy() end) end
    end
    for _, name in ipairs({"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot"}) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            part.Transparency = 0
            part.LocalTransparencyModifier = 0
        end
    end
end

local function attachVisionKroblox(whichLeg)
    local data = VISION_KROBLOX_ASSETS[whichLeg]
    local character = LP.Character
    if not data or not character then return false end
    local target = character:FindFirstChild(data.targetBodyPart)
    if not target then return false end
    local old = character:FindFirstChild("Korblox_" .. whichLeg:gsub("%s+", ""))
    if old then old:Destroy() end
    for _, name in ipairs(data.partsToHide) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then part.Transparency = 1 end
    end
    local ok, objects = pcall(function() return game:GetObjects(data.id) end)
    if not ok or not objects or #objects == 0 then return false end
    local object = objects[1]
    object.Name = "Korblox_" .. whichLeg:gsub("%s+", "")
    local meshPart = object:IsA("BasePart") and object or object:FindFirstChildWhichIsA("BasePart", true)
    if not meshPart then pcall(function() object:Destroy() end); return false end
    meshPart.Size = meshPart.Size * data.scale
    meshPart.CanCollide = false
    meshPart.CanTouch = false
    meshPart.CanQuery = false
    meshPart.Massless = true
    meshPart.CFrame = target.CFrame * data.offset
    local weld = Instance.new("WeldConstraint")
    weld.Part0 = target
    weld.Part1 = meshPart
    weld.Parent = meshPart
    object.Parent = character
    return true
end

_G._VisionApplyKroblox = function(mode)
    mode = ({Off=true, Left=true, Right=true, Both=true})[mode] and mode or "Off"
    clearVisionKroblox()
    S.krobloxMode = mode
    _G._VisionKrobloxMode = mode
    if mode == "Left" or mode == "Both" then pcall(attachVisionKroblox, "Left Leg") end
    if mode == "Right" or mode == "Both" then pcall(attachVisionKroblox, "Right Leg") end
end

LP.CharacterAdded:Connect(function()
    task.wait(0.6)
    if _G._VisionKrobloxMode ~= "Off" then
        pcall(_G._VisionApplyKroblox, _G._VisionKrobloxMode)
    end
end)

-- ── Tab content builders ──────────────────────────────────────────────────
local function mkAimbotSpeedSlider(pg, pages, label, initialValue, onChanged, stepSize)
    local card = mkCard(pg, pages, 58)
    card.Name = "AimbotSpeed_" .. tostring(label):gsub("[^%w]+", "_")

    local title = Instance.new("TextLabel", card)
    title.Name = "SpeedTitle"
    title.Size = UDim2.new(1, -92, 0, 20)
    title.Position = UDim2.fromOffset(12, 5)
    title.BackgroundTransparency = 1
    title.Text = label
    title.TextColor3 = C_WHITE
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left

    local valueLabel = Instance.new("TextLabel", card)
    valueLabel.Name = "SpeedValue"
    valueLabel.Size = UDim2.fromOffset(66, 20)
    valueLabel.Position = UDim2.new(1, -78, 0, 5)
    valueLabel.BackgroundTransparency = 1
    valueLabel.TextColor3 = C_HIGHLIGHT
    valueLabel.Font = Enum.Font.GothamBlack
    valueLabel.TextSize = 11
    valueLabel.TextXAlignment = Enum.TextXAlignment.Right

    local track = Instance.new("Frame", card)
    track.Name = "SpeedTrack"
    track.Active = true
    track.Size = UDim2.new(1, -30, 0, 6)
    track.Position = UDim2.fromOffset(15, 39)
    track.BackgroundColor3 = Color3.fromRGB(38, 28, 37)
    track.BorderSizePixel = 0
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

    local fill = Instance.new("Frame", track)
    fill.Name = "Fill"
    fill.Size = UDim2.fromScale(0, 1)
    fill.BackgroundColor3 = C_HIGHLIGHT
    fill.BorderSizePixel = 0
    fill.Active = false
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

    local knob = Instance.new("TextButton", track)
    knob.Name = "Knob"
    knob.Size = UDim2.fromOffset(16, 16)
    knob.AnchorPoint = Vector2.new(0.5, 0.5)
    knob.Position = UDim2.new(0, 0, 0.5, 0)
    knob.BackgroundColor3 = C_WHITE
    knob.BorderSizePixel = 0
    knob.Text = ""
    knob.AutoButtonColor = false
    knob.ZIndex = 4
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
    local knobStroke = Instance.new("UIStroke", knob)
    knobStroke.Color = C_HIGHLIGHT
    knobStroke.Thickness = 1.2

    local currentValue = math.clamp(tonumber(initialValue) or 55, 1, 120)
    local increment = math.max(tonumber(stepSize) or 1, 0.1)
    local dragging = false

    local function setValue(rawValue, persist)
        local raw = math.clamp(tonumber(rawValue) or currentValue, 1, 120)
        currentValue = math.clamp(1 + math.floor(((raw - 1) / increment) + 0.5) * increment, 1, 120)
        local ratio = (currentValue - 1) / 119
        valueLabel.Text = increment < 1 and string.format("%.1f", currentValue) or tostring(math.floor(currentValue + 0.5))
        fill.Size = UDim2.new(ratio, 0, 1, 0)
        knob.Position = UDim2.new(ratio, 0, 0.5, 0)
        if onChanged then pcall(onChanged, currentValue, persist == true) end
    end

    local function ratioFromInput(input)
        local width = math.max(track.AbsoluteSize.X, 1)
        return math.clamp((input.Position.X - track.AbsolutePosition.X) / width, 0, 1)
    end

    local function beginDrag(input)
        if input.UserInputType ~= Enum.UserInputType.Touch
            and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        dragging = true
        setValue(1 + ratioFromInput(input) * 119, false)
    end

    track.InputBegan:Connect(beginDrag)
    knob.InputBegan:Connect(beginDrag)
    UIS.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.Touch
            or input.UserInputType == Enum.UserInputType.MouseMovement then
            setValue(1 + ratioFromInput(input) * 119, false)
        end
    end)
    UIS.InputEnded:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.Touch
            or input.UserInputType == Enum.UserInputType.MouseButton1) then
            dragging = false
            setValue(currentValue, true)
        end
    end)

    setValue(currentValue, false)
    return function(value)
        setValue(value, false)
    end
end

local function buildSpeedTab(pages)
    mkSection("Speed", pages, "Speed Values")
    S.normalBox  = mkInput("Speed", pages, "Normal Speed",   S.NS, function(v)
        if v>0 and v<=500 then S.NS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.carryBox   = mkInput("Speed", pages, "Carry Speed",    S.CS, function(v)
        if v>0 and v<=500 then S.CS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.laggerBox  = mkInput("Speed", pages, "Lagger Normal Speed", S.LS, function(v)
        if v>0 and v<=500 then S.LS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.laggerCarryBox = mkInput("Speed", pages, "Lagger Carry Speed", S.LCS, function(v)
        if v>0 and v<=500 then S.LCS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    mkSection("Speed", pages, "Modes")
    S.speedClk, _ = mkToggle("Speed", pages, "Carry Mode", S.KB.SpeedToggle.kb, S.speedMode, function(on)
        if on and S.laggerMode~=0 then S.laggerMode=0; if S.setLaggerVisual then S.setLaggerVisual(false) end; updateLaggerButtonVisual() end
        S.speedMode = on
        if on then S.setCarrySpeedMode() else S.setNormalSpeedMode() end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.SpeedToggle.gp=k; S.KB.SpeedToggle.kb=nil
        else S.KB.SpeedToggle.kb=k; S.KB.SpeedToggle.gp=nil end; saveConfig()
    end)
    S.setLaggerVisual, _ = mkToggle("Speed", pages, "Lagger Mode", S.KB.LaggerToggle.kb, S.laggerMode ~= 0, function(on)
        if on then
            if S.speedClk then S.speedClk(false) end
            S.setLaggerNormalMode()
        else
            S.setLaggerOffMode()
        end
        updateLaggerButtonVisual(); S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.LaggerToggle.gp=k; S.KB.LaggerToggle.kb=nil
        else S.KB.LaggerToggle.kb=k; S.KB.LaggerToggle.gp=nil end; saveConfig()
    end)

    -- Each slider controls one engine only. The values are applied live and
    -- written to config when the user releases the slider.
    mkSection("Speed", pages, "Aimbot Speed Controls")
    mkAimbotSpeedSlider("Speed", pages, "AIMBOT V1 SPEED", S.aimbotV1Speed, function(value, persist)
        S.aimbotV1Speed = value
        _linxAimbotSpeed = value
        if persist then saveConfig() end
    end, 1)
    mkAimbotSpeedSlider("Speed", pages, "BAT AIMBOT V2 SPEED", S.aimbotV2Speed, function(value, persist)
        value = math.floor(value + 0.5)
        S.aimbotV2Speed = value
        _G.__XYPHER_PENDING_V11_SPEED = value
        if type(_G.FRHUBV11SetSpeed) == "function" then pcall(_G.FRHUBV11SetSpeed, value) end
        if persist then saveConfig() end
    end, 1)
    mkAimbotSpeedSlider("Speed", pages, "ANTI-BAT AIMBOT SPEED", S.antiBatAimbotSpeed, function(value, persist)
        S.antiBatAimbotSpeed = value
        _G.__XYPHER_PENDING_ANTIBAT_AIMBOT_SPEED = value
        if type(_G.SetAntiBatBypassSpeed) == "function" then pcall(_G.SetAntiBatBypassSpeed, value) end
        if persist then saveConfig() end
    end, 1)
    mkAimbotSpeedSlider("Speed", pages, "AIMBOT BYPASS V4 SPEED", S.aimbotBypassV4Speed, function(value, persist)
        S.aimbotBypassV4Speed = value
        _G.__XYPHER_PENDING_BYPASS_V4_SPEED = value
        if type(_G.XYPHER_SetAimbotV4Speed) == "function" then pcall(_G.XYPHER_SetAimbotV4Speed, value) end
        if persist then saveConfig() end
    end, 0.5)
end

-- ==================== VISION BAT SKINS ====================
do
-- Ported from Zurich: Epic Katana and Bloody Katana, including their slash sounds.
VisionBatSkin = {}
VISION_BAT_SKINS = {
    {name = "Off"},
    {
        name = "Epic Katana",
        id = "rbxassetid://14052995337",
        soundId = "rbxassetid://111808555599832",
        c0 = CFrame.new(0, 0, 1.6) * CFrame.Angles(0, 0, math.rad(-90)),
    },
    {
        name = "Bloody Katana",
        id = "rbxassetid://126653333198410",
        soundId = "rbxassetid://111808555599832",
        c0 = CFrame.new(0, 0, 2) * CFrame.Angles(math.rad(90), 0, 0),
    },
}
VisionBatSkin.cache = {}
VisionBatSkin.originals = setmetatable({}, {__mode = "k"})
VisionBatSkin.soundConnections = setmetatable({}, {__mode = "k"})
VisionBatSkin.watched = setmetatable({}, {__mode = "k"})

function VisionBatSkin.visionLoadBatSkin(id)
    if VisionBatSkin.cache[id] then return VisionBatSkin.cache[id] end
    local ok, objects = pcall(function() return game:GetObjects(id) end)
    if not ok or type(objects) ~= "table" or #objects == 0 then return nil end
    VisionBatSkin.cache[id] = objects[1]
    return objects[1]
end

function VisionBatSkin.visionIsBat(tool)
    return tool and tool:IsA("Tool") and tool.Name:lower() == "bat"
end

function VisionBatSkin.visionSetBatSlashSound(tool, soundId)
    if not tool then return end
    for _, sound in ipairs(tool:GetDescendants()) do
        if sound:IsA("Sound") and sound.Name == "Slash" then
            local original = sound:GetAttribute("VisionOriginalSlashSound")
            if soundId then
                if original == nil then sound:SetAttribute("VisionOriginalSlashSound", sound.SoundId) end
                sound.SoundId = soundId
            elseif original ~= nil then
                sound.SoundId = original
                sound:SetAttribute("VisionOriginalSlashSound", nil)
            end
        end
    end
end

function VisionBatSkin.visionRestoreBatSkin(tool, clearOriginal)
    if not VisionBatSkin.visionIsBat(tool) then return end
    local handle = tool:FindFirstChild("Handle")
    local original = VisionBatSkin.originals[tool]
    if handle then
        -- En Off no debe quedar visible ningún modelo, weld o parte de la skin.
        for _, child in ipairs(handle:GetChildren()) do
            if not child:IsA("Sound") then
                pcall(function() child:Destroy() end)
            end
        end
    end
    if handle and original then
        handle.Transparency = original.transparency
        handle.CanCollide = original.canCollide
        handle.CanTouch = original.canTouch
        handle.CanQuery = original.canQuery
        handle.Size = original.size
    elseif handle then
        handle.Transparency = 0
    end
    if original and original.grip then tool.Grip = original.grip end
    VisionBatSkin.visionSetBatSlashSound(tool, nil)
    local soundConnection = VisionBatSkin.soundConnections[tool]
    if clearOriginal ~= false and soundConnection then
        pcall(function() soundConnection:Disconnect() end)
        VisionBatSkin.soundConnections[tool] = nil
    end
    if clearOriginal ~= false then VisionBatSkin.originals[tool] = nil end
end

function VisionBatSkin.visionPrepareBatSkin(tool, entry)
    if not VisionBatSkin.visionIsBat(tool) or not entry or not entry.id then return end
    local toolHandle = tool:FindFirstChild("Handle")
    if not toolHandle then return end

    if not VisionBatSkin.originals[tool] then
        VisionBatSkin.originals[tool] = {
            grip = tool.Grip,
            transparency = toolHandle.Transparency,
            canCollide = toolHandle.CanCollide,
            canTouch = toolHandle.CanTouch,
            canQuery = toolHandle.CanQuery,
            size = toolHandle.Size,
        }
    end

    VisionBatSkin.visionRestoreBatSkin(tool, false)
    for _, child in ipairs(toolHandle:GetChildren()) do
        if not child:IsA("Sound") then pcall(function() child:Destroy() end) end
    end

    local katanaRoot = VisionBatSkin.visionLoadBatSkin(entry.id)
    if not katanaRoot then return end
    local modelClone = katanaRoot:Clone()
    modelClone.Name = "VisionBatSkinModel"
    modelClone.Parent = toolHandle

    local function makeKinematic(inst)
        if inst:IsA("BasePart") then
            inst.Anchored = false
            inst.CanCollide = false
            inst.Massless = true
        end
        for _, child in ipairs(inst:GetChildren()) do makeKinematic(child) end
    end
    makeKinematic(modelClone)

    local primaryPart = modelClone:IsA("BasePart") and modelClone or modelClone.PrimaryPart
    if not primaryPart then
        for _, inst in ipairs(modelClone:GetDescendants()) do
            if inst:IsA("BasePart") then primaryPart = inst; break end
        end
    end
    if not primaryPart then pcall(function() modelClone:Destroy() end); return end

    local weld = Instance.new("Weld")
    weld.Part0 = toolHandle
    weld.Part1 = primaryPart
    weld.C0 = entry.c0
    weld.Parent = toolHandle

    toolHandle.Transparency = 1
    toolHandle.CanCollide = false
    toolHandle.Size = Vector3.new(0.3, 1, 0.3)
    tool.GripForward = Vector3.new(0, -1, 0)
    tool.GripRight   = Vector3.new(1,  0, 0)
    tool.GripUp      = Vector3.new(0,  0, 1)
    tool.GripPos     = Vector3.new(0,  0, 0)

    local previousSoundConnection = VisionBatSkin.soundConnections[tool]
    if previousSoundConnection then
        pcall(function() previousSoundConnection:Disconnect() end)
        VisionBatSkin.soundConnections[tool] = nil
    end
    VisionBatSkin.visionSetBatSlashSound(tool, entry.soundId)
    VisionBatSkin.soundConnections[tool] = tool.DescendantAdded:Connect(function(obj)
        if S.batSkinMode == entry.name and obj:IsA("Sound") and obj.Name == "Slash" then
            if obj:GetAttribute("VisionOriginalSlashSound") == nil then
                obj:SetAttribute("VisionOriginalSlashSound", obj.SoundId)
            end
            obj.SoundId = entry.soundId
        end
    end)
end

function VisionBatSkin.visionApplyBatSkin(tool)
    if not VisionBatSkin.visionIsBat(tool) then return end
    if S.batSkinMode == "Off" then
        VisionBatSkin.visionRestoreBatSkin(tool)
        return
    end
    local entry
    for _, candidate in ipairs(VISION_BAT_SKINS) do
        if candidate.name == S.batSkinMode then entry = candidate; break end
    end
    if entry then VisionBatSkin.visionPrepareBatSkin(tool, entry) end
end

function VisionBatSkin.visionScanBatSkins(parent)
    if not parent then return end
    for _, child in ipairs(parent:GetChildren()) do
        if VisionBatSkin.visionIsBat(child) then task.spawn(VisionBatSkin.visionApplyBatSkin, child) end
    end
end

function VisionBatSkin.visionWatchBatSkinContainer(parent)
    if not parent or VisionBatSkin.watched[parent] then return end
    VisionBatSkin.watched[parent] = true
    table.insert(S.batSkinConnections, parent.ChildAdded:Connect(function(child)
        task.wait(0.1)
        if VisionBatSkin.visionIsBat(child) then VisionBatSkin.visionApplyBatSkin(child) end
    end))
    VisionBatSkin.visionScanBatSkins(parent)
end

function VisionBatSkin.visionWatchBatSkinCharacter(character)
    VisionBatSkin.visionWatchBatSkinContainer(character)
    VisionBatSkin.visionWatchBatSkinContainer(LP:FindFirstChildOfClass("Backpack"))
    if S.batSkinMode ~= "Off" then
        task.delay(0.35, function()
            if LP.Character == character then
                VisionBatSkin.visionScanBatSkins(character)
                VisionBatSkin.visionScanBatSkins(LP:FindFirstChildOfClass("Backpack"))
            end
        end)
    end
end

function VisionBatSkin.visionSetBatSkin(mode, shouldSave)
    local valid = false
    for _, entry in ipairs(VISION_BAT_SKINS) do
        if entry.name == mode then valid = true; break end
    end
    S.batSkinMode = valid and mode or "Off"
    VisionBatSkin.visionScanBatSkins(LP.Character)
    VisionBatSkin.visionScanBatSkins(LP:FindFirstChildOfClass("Backpack"))
    if S.batSkinSelectorLabel then S.batSkinSelectorLabel.Text = S.batSkinMode end
    if shouldSave then saveConfig() end
end

function VisionBatSkin.visionCycleBatSkin(direction)
    local index = 1
    for i, entry in ipairs(VISION_BAT_SKINS) do
        if entry.name == S.batSkinMode then index = i; break end
    end
    index = index + (direction or 1)
    if index < 1 then index = #VISION_BAT_SKINS end
    if index > #VISION_BAT_SKINS then index = 1 end
    VisionBatSkin.visionSetBatSkin(VISION_BAT_SKINS[index].name, true)
end

S.setBatSkin = VisionBatSkin.visionSetBatSkin
S.cycleBatSkin = VisionBatSkin.visionCycleBatSkin

LP.CharacterAdded:Connect(function(character)
    task.wait(0.2)
    VisionBatSkin.visionWatchBatSkinCharacter(character)
end)
LP.ChildAdded:Connect(function(child)
    if child:IsA("Backpack") then VisionBatSkin.visionWatchBatSkinContainer(child) end
end)
VisionBatSkin.visionWatchBatSkinCharacter(LP.Character)
end

-- ==================== VISION DISPLAY MODE / COMPLETE SKINS ====================
do
VisionDisplaySkin = {}
VISION_SKIN_ORDER = {"Off", "PURPLE", "BLUE", "RED", "BLACK", "GREEN", "WHITE"}
VISION_SKIN_SETS = {
    PURPLE = {hats="1744060292,439945661,1125510,1029025", hair="", headless=true, korblox="Right", accessories={1744060292,439945661,1125510,1029025,11748356,8465506143,11444217173}, clothing={7424637509,7689651773}, color=Color3.fromRGB(145,88,255)},
    BLUE = {hats="74891470", hair="16630147,6346833550,6594911228,6594919952,6823338112,7097747842", headless=true, korblox="Right", accessories={74891470,16630147,6346833550,6594911228,6594919952,6823338112,7097747842}, clothing={18423061209,18423154566}, color=Color3.fromRGB(55,145,255)},
    RED = {hats="215718515,439945661", hair="7183785281", headless=true, korblox="Right", accessories={215718515,439945661,7183785281}, clothing={15998365201,7689651773}, color=Color3.fromRGB(235,62,72)},
    BLACK = {hats="10159600649,439946249,17798262442,92482095662016", hair="139101716417676", headless=true, korblox="Right", accessories={10159600649,439946249,17798262442,92482095662016,139101716417676,12490213797}, clothing={18766106994,13925390578}, color=Color3.fromRGB(24,24,30)},
    GREEN = {hats="553970961,1744060292", hair="93268856876777", headless=true, korblox="Right", accessories={553970961,1744060292,93268856876777}, clothing={9478068776,6348682339}, color=Color3.fromRGB(62,210,112)},
    WHITE = {hats="74891470,215718515,439945661,1016143686,1744060292,10159600649,89012651581593,88365652378427", hair="126447390530523", headless=true, korblox="Right", accessories={74891470,215718515,439945661,1016143686,1744060292,10159600649,89012651581593,126447390530523}, clothing={88032876921227,108259950755140}, color=Color3.fromRGB(238,238,244)},
}
VISION_ASSET_PROPERTIES = {
    [1744060292]="HatAccessory", [439945661]="HatAccessory", [1125510]="HatAccessory", [1029025]="HatAccessory", [8465506143]="HatAccessory", [74891470]="HatAccessory", [215718515]="HatAccessory", [10159600649]="HatAccessory", [439946249]="HatAccessory", [17798262442]="HatAccessory", [92482095662016]="HatAccessory", [553970961]="HatAccessory", [1016143686]="HatAccessory", [89012651581593]="HatAccessory", [88365652378427]="HatAccessory",
    [16630147]="HairAccessory", [6346833550]="HairAccessory", [6594911228]="HairAccessory", [6594919952]="HairAccessory", [6823338112]="HairAccessory", [7097747842]="HairAccessory", [7183785281]="HairAccessory", [139101716417676]="HairAccessory", [93268856876777]="HairAccessory", [126447390530523]="HairAccessory",
    [11748356]="FaceAccessory", [12490213797]="FaceAccessory", [11444217173]="NeckAccessory",
    [7424637509]="Shirt", [18423061209]="Shirt", [15998365201]="Shirt", [18766106994]="Shirt", [9478068776]="Shirt", [88032876921227]="Shirt",
    [7689651773]="Pants", [18423154566]="Pants", [13925390578]="Pants", [6348682339]="Pants", [108259950755140]="Pants",
}
VisionOriginalDescriptions = setmetatable({}, {__mode="k"})
VisionOriginalOutfits = setmetatable({}, {__mode="k"})
VisionDisplaySkin._assetCache = {}
VisionDisplaySkin._applying = false
VisionDisplaySkin._pendingToken = nil

function VisionDisplaySkin.assetInSet(id, setData)
    id=tonumber(id); if not id or not setData then return false end
    for _,v in ipairs(setData.accessories or {}) do if id==v then return true end end
    for _,v in ipairs(setData.clothing or {}) do if id==v then return true end end
    return false
end
function VisionDisplaySkin.appendDescriptionAsset(description, id)
    local property=VISION_ASSET_PROPERTIES[tonumber(id)]
    if not property then return end
    if property=="Shirt" or property=="Pants" then description[property]=tonumber(id); return end
    local old=tostring(description[property] or "")
    if not old:find(tostring(id),1,true) then description[property]=(old=="" and tostring(id) or old..","..tostring(id)) end
end
function VisionDisplaySkin.buildDescription(setName, character)
    local setData=VISION_SKIN_SETS[setName]; if not setData then return nil end
    local humanoid=character and character:FindFirstChildOfClass("Humanoid"); if not humanoid then return nil end
    local description
    pcall(function() description=humanoid:GetAppliedDescription():Clone() end)
    if not description then pcall(function() description=Players:GetHumanoidDescriptionFromUserId(LP.UserId) end) end
    if not description then description=Instance.new("HumanoidDescription") end
    for _,property in ipairs({"HatAccessory","HairAccessory","FaceAccessory","NeckAccessory","ShouldersAccessory","FrontAccessory","BackAccessory","WaistAccessory","ShirtAccessory","PantsAccessory","JacketAccessory","SweaterAccessory","ShortsAccessory","TShirtAccessory","DressSkirtAccessory"}) do pcall(function() description[property]="" end) end
    pcall(function() description.Shirt=0; description.Pants=0; description.GraphicTShirt=0; description.HatAccessory=setData.hats or ""; description.HairAccessory=setData.hair or "" end)
    for _,id in ipairs(setData.accessories or {}) do VisionDisplaySkin.appendDescriptionAsset(description,id) end
    for _,id in ipairs(setData.clothing or {}) do VisionDisplaySkin.appendDescriptionAsset(description,id) end
    return description
end
function VisionDisplaySkin.applyDescription(humanoid, description)
    if not humanoid or not description then return false end

    -- Use a single description application. Trying several ApplyDescription
    -- variants in sequence can force multiple avatar rebuilds in one frame.
    local copy
    local ok = pcall(function() copy = description:Clone() end)
    if not ok or not copy then return false end

    local applied = false
    pcall(function()
        local method = humanoid.ApplyDescription
        if type(method) == "function" then
            method(humanoid, copy)
            applied = true
        end
    end)

    pcall(function() copy:Destroy() end)
    return applied
end
function VisionDisplaySkin.captureOriginalOutfit(character)
    if VisionOriginalOutfits[character] then return end
    local saved={}
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            local ok,clone=pcall(function() return child:Clone() end)
            if ok and clone then saved[#saved+1]=clone end
        end
    end
    VisionOriginalOutfits[character]=saved
end
function VisionDisplaySkin.restoreOriginalOutfit(character)
    local saved=VisionOriginalOutfits[character]
    if not saved then return end
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then pcall(function() child:Destroy() end) end
    end
    local humanoid=character:FindFirstChildOfClass("Humanoid")
    for _,clone in ipairs(saved) do
        local copy=clone:Clone()
        if copy:IsA("Accessory") and humanoid then VisionDisplaySkin.attachAccessory(character,humanoid,copy) else copy.Parent=character end
    end
end

function VisionDisplaySkin.clearMarked(character)
    for _,child in ipairs(character:GetChildren()) do
        if child:GetAttribute("VisionCompleteSkin") then pcall(function() child:Destroy() end) end
    end
end
function VisionDisplaySkin.markAndColor(character, setData)
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            local id
            pcall(function() id=tonumber(child.SourceAssetId) end)
            if VisionDisplaySkin.assetInSet(id,setData) then child:SetAttribute("VisionCompleteSkin",true) end
        end
    end
    for _,descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            local parent=descendant
            while parent and parent~=character do
                if parent:GetAttribute("VisionCompleteSkin") then descendant.Color=setData.color; break end
                parent=parent.Parent
            end
        end
    end
end
function VisionDisplaySkin.setHeadless(character, enabled)
    local head=character and character:FindFirstChild("Head"); if not head then return end
    local transparency=enabled and 1 or 0; head.Transparency=transparency; head.LocalTransparencyModifier=transparency
    for _,child in ipairs(head:GetChildren()) do if child:IsA("Decal") or child:IsA("Texture") then child.Transparency=transparency end end
end
function VisionDisplaySkin.attachAccessory(character, humanoid, accessory)
    local handle=accessory:FindFirstChild("Handle",true)
    pcall(function() humanoid:AddAccessory(accessory) end)
    if not accessory.Parent then accessory.Parent=character end
    if not handle or not handle:IsA("BasePart") then return accessory.Parent==character end
    local handleAttachment=handle:FindFirstChildWhichIsA("Attachment")
    if not handleAttachment then return accessory.Parent==character end
    local targetAttachment
    for _,descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("Attachment") and descendant.Name==handleAttachment.Name and not descendant:IsDescendantOf(accessory) then targetAttachment=descendant; break end
    end
    if targetAttachment and targetAttachment.Parent:IsA("BasePart") then
        handle.Anchored=false; handle.CanCollide=false; handle.CanTouch=false; handle.CanQuery=false; handle.Massless=true
        handle.CFrame=targetAttachment.Parent.CFrame*targetAttachment.CFrame*handleAttachment.CFrame:Inverse()
        if not handle:FindFirstChild("VisionAccessoryWeld") then
            local weld=Instance.new("WeldConstraint"); weld.Name="VisionAccessoryWeld"; weld.Part0=targetAttachment.Parent; weld.Part1=handle; weld.Parent=handle
        end
    end
    return accessory.Parent==character
end
function VisionDisplaySkin.hasAsset(character, assetId)
    assetId=tonumber(assetId)
    for _,child in ipairs(character:GetChildren()) do
        local sourceId
        pcall(function() sourceId=tonumber(child.SourceAssetId) end)
        if assetId and assetId>0 then
            if sourceId==assetId or tonumber(child:GetAttribute("VisionSkinAssetId"))==assetId then return true end
        end
    end
    return false
end
function VisionDisplaySkin.addAsset(character, humanoid, assetId)
    assetId = tonumber(assetId)
    if not assetId or assetId <= 0 or VisionDisplaySkin.hasAsset(character, assetId) then return true end

    -- Cache the source template so changing skins repeatedly does not reload
    -- the same Roblox asset every time. Only the cached template is cloned.
    local cached = VisionDisplaySkin._assetCache[assetId]
    if not cached then
        local ok, objects = pcall(function()
            return game:GetObjects("rbxassetid://" .. tostring(assetId))
        end)
        if ok and type(objects) == "table" and #objects > 0 then
            cached = objects[1]
        else
            local loaded
            pcall(function() loaded = game:GetService("InsertService"):LoadAsset(assetId) end)
            cached = loaded
        end
        if cached then
            local okClone, template = pcall(function() return cached:Clone() end)
            if okClone and template then
                VisionDisplaySkin._assetCache[assetId] = template
            end
            pcall(function() cached:Destroy() end)
            cached = VisionDisplaySkin._assetCache[assetId]
        end
    end

    if not cached then return false end

    local candidates = {}
    if cached:IsA("Accessory") or cached:IsA("Shirt") or cached:IsA("Pants") or cached:IsA("ShirtGraphic") then
        candidates[1] = cached
    else
        for _, descendant in ipairs(cached:GetDescendants()) do
            if descendant:IsA("Accessory") or descendant:IsA("Shirt") or descendant:IsA("Pants") or descendant:IsA("ShirtGraphic") then
                candidates[#candidates + 1] = descendant
            end
        end
    end

    local added = false
    for _, source in ipairs(candidates) do
        local okClone, clone = pcall(function() return source:Clone() end)
        if okClone and clone then
            clone:SetAttribute("VisionCompleteSkin", true)
            clone:SetAttribute("VisionSkinAssetId", assetId)
            if clone:IsA("Accessory") then
                if VisionDisplaySkin.attachAccessory(character, humanoid, clone) then added = true end
            else
                for _, old in ipairs(character:GetChildren()) do
                    if old.ClassName == clone.ClassName and old:GetAttribute("VisionCompleteSkin") then
                        pcall(function() old:Destroy() end)
                    end
                end
                clone.Parent = character
                added = true
            end
        end
    end
    return added
end

function VisionDisplaySkin.applyAccessories(character, humanoid, description, setData)
    local source
    pcall(function() source=Players:CreateHumanoidModelFromDescriptionAsync(description,Enum.HumanoidRigType.R15) end)
    if not source then pcall(function() source=Players:CreateHumanoidModelFromDescription(description,Enum.HumanoidRigType.R15) end) end
    if not source then return end
    for _,child in ipairs(source:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            if child:IsA("Accessory") then
                local sourceId; pcall(function() sourceId=tonumber(child.SourceAssetId) end)
                if not VisionDisplaySkin.hasAsset(character,sourceId) then
                    local clone=child:Clone(); clone:SetAttribute("VisionCompleteSkin",true); clone:SetAttribute("VisionSkinAssetId",sourceId)
                    VisionDisplaySkin.attachAccessory(character,humanoid,clone)
                end
            else
                for _,current in ipairs(character:GetChildren()) do if current.ClassName==child.ClassName then pcall(function() current:Destroy() end) end end
                local clone=child:Clone(); clone:SetAttribute("VisionCompleteSkin",true); clone.Parent=character
            end
        end
    end
    source:Destroy(); VisionDisplaySkin.markAndColor(character,setData)
end

function VisionDisplaySkin.apply(token)
    token = token or S._skinApplyToken
    if VisionDisplaySkin._applying then
        VisionDisplaySkin._pendingToken = token
        return
    end

    local character = LP.Character
    local setName = S.displaySkin
    if token ~= S._skinApplyToken or not character or setName == "Off" or not S.customSkinEnabled then return end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local setData = VISION_SKIN_SETS[setName]
    if not humanoid or not setData then return end

    VisionDisplaySkin._applying = true
    VisionDisplaySkin._pendingToken = nil

    local ok, err = pcall(function()
        if not VisionOriginalDescriptions[character] then
            pcall(function() VisionOriginalDescriptions[character] = humanoid:GetAppliedDescription():Clone() end)
        end
        VisionDisplaySkin.captureOriginalOutfit(character)

        -- Replace only the visible outfit parts. This avoids forcing Roblox to
        -- rebuild the whole humanoid with ApplyDescription on every skin switch.
        VisionDisplaySkin.clearMarked(character)
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Accessory") or child:IsA("Accoutrement")
                or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
                pcall(function() child:Destroy() end)
            end
        end
        if token ~= S._skinApplyToken then return end

        -- Add only the requested assets once. hasAsset() prevents duplicates.
        for _, id in ipairs(setData.accessories or {}) do
            if token ~= S._skinApplyToken then return end
            VisionDisplaySkin.addAsset(character, humanoid, id)
        end
        for _, id in ipairs(setData.clothing or {}) do
            if token ~= S._skinApplyToken then return end
            VisionDisplaySkin.addAsset(character, humanoid, id)
        end

        VisionDisplaySkin.markAndColor(character, setData)
        VisionDisplaySkin.setHeadless(character, setData.headless == true)
        if type(_G._VisionApplyKroblox) == "function" and token == S._skinApplyToken then
            pcall(_G._VisionApplyKroblox, setData.korblox or "Off")
        end
    end)

    VisionDisplaySkin._applying = false
    if not ok then warn("[Vision] Custom avatar apply error: " .. tostring(err)) end

    local pending = VisionDisplaySkin._pendingToken
    VisionDisplaySkin._pendingToken = nil
    if pending and pending == S._skinApplyToken and S.customSkinEnabled and S.displaySkin ~= "Off" then
        task.defer(function() VisionDisplaySkin.apply(pending) end)
    end
end

function VisionDisplaySkin.off()
    local character = LP.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")

    -- Invalidate running apply jobs before restoring the original avatar.
    S._skinApplyToken = S._skinApplyToken + 1
    VisionDisplaySkin._pendingToken = nil

    VisionDisplaySkin.clearMarked(character)
    local restoredByDescription = false
    if humanoid and VisionOriginalDescriptions[character] then
        local original = VisionOriginalDescriptions[character]:Clone()
        restoredByDescription = VisionDisplaySkin.applyDescription(humanoid, original)
        pcall(function() original:Destroy() end)
    end
    -- Only use the manual outfit restore if the description restore failed;
    -- doing both can duplicate accessories and create a visible hitch.
    if not restoredByDescription then
        VisionDisplaySkin.restoreOriginalOutfit(character)
    end
    VisionDisplaySkin.setHeadless(character, false)
    if type(_G._VisionApplyKroblox) == "function" then pcall(_G._VisionApplyKroblox, "Off") end
end
function VisionDisplaySkin.setSkin(name,save)
    S._skinApplyToken = S._skinApplyToken + 1
    local myToken = S._skinApplyToken
    local valid = false
    for _,v in ipairs(VISION_SKIN_ORDER) do if v == name then valid = true end end
    S.displaySkin = valid and name or "Off"
    if S.displaySkin == "Off" then
        S.customSkinEnabled = false
        VisionDisplaySkin.off()
    else
        S.customSkinEnabled = true
        task.spawn(function() VisionDisplaySkin.apply(myToken) end)
    end
    if S.displaySkinSelectorLabel then S.displaySkinSelectorLabel.Text = S.displaySkin end
    if S.customSkinVisual then S.customSkinVisual(S.customSkinEnabled) end
    if save then saveConfig() end
end
function VisionDisplaySkin.cycleSkin(direction)
    local index=1; for i,v in ipairs(VISION_SKIN_ORDER) do if v==S.displaySkin then index=i end end
    index=index+(direction or 1); if index<1 then index=#VISION_SKIN_ORDER end; if index>#VISION_SKIN_ORDER then index=1 end
    VisionDisplaySkin.setSkin(VISION_SKIN_ORDER[index],true)
end
function VisionDisplaySkin.setCustom(on)
    S._skinApplyToken=S._skinApplyToken+1
    local myToken=S._skinApplyToken
    S.customSkinEnabled=on==true
    if S.customSkinEnabled then if S.displaySkin=="Off" then S.displaySkin="PURPLE" end; task.spawn(function() VisionDisplaySkin.apply(myToken) end) else VisionDisplaySkin.off() end
    if S.customSkinVisual then S.customSkinVisual(S.customSkinEnabled) end
    if S.displaySkinSelectorLabel then S.displaySkinSelectorLabel.Text=S.displaySkin end
    saveConfig()
end
S.setDisplaySkin=VisionDisplaySkin.setSkin; S.cycleDisplaySkin=VisionDisplaySkin.cycleSkin; S.setCustomSkin=VisionDisplaySkin.setCustom
S.applyDisplaySkin=function(token) return VisionDisplaySkin.apply(token) end
LP.CharacterAdded:Connect(function(character)
    VisionOriginalDescriptions[character] = nil
    VisionOriginalOutfits[character] = nil
    if S.customSkinEnabled and S.displaySkin ~= "Off" then
        local token = S._skinApplyToken
        task.defer(function()
            if LP.Character == character and S.customSkinEnabled and S.displaySkin ~= "Off" and token == S._skinApplyToken then
                VisionDisplaySkin.apply(token)
            end
        end)
    end
end)
end

-- ============================================================
-- SC Vision Nuke Optimizer integration
-- Imported from Nuke_Optimizer_Logic.lua. Disabled by default.
-- Avatar protection patch: all player characters and marked custom-avatar trees are excluded.
-- Private globals are namespaced to avoid collisions with other hubs.
-- ============================================================
-- Clean up an older execution of this same integrated module first.
if type(_G.__SCVisionNukeStop) == "function" then
    pcall(_G.__SCVisionNukeStop)
end
_G.__SCVisionNukeOn = false
_G.__SCVisionNukeConns = {}
_G.__SCVisionNukeThreads = {}

(function()
-- Nuke Optimizer — logic-only extraction from Zero Hub.
-- Source basis: Zero_hub_mobile_button_background_final.lua
-- The original UI/toggle is not included.
--
-- Usage:
--   _G.__SCVisionNukeStart()  -- enable optimizer
--   _G.__SCVisionNukeStop()   -- disable optimizer
--   _G.__SCVisionNukeToggle(true/false)
--
-- Optional Minecraft texture integration uses globals/hooks when available.
-- This module is disabled by default and does not auto-start.

-- ============================================================
-- NUKE OPTIMIZER INTEGRATION
-- Added as a GUI-controlled feature; disabled by default.
-- ============================================================
-- Nuke Optimizer - extracted from Vasper_v3.5_AntiE01_AutoSteal_SEMI_CHECKED_FIXED.lua
-- Standalone extraction.
-- Toggle:
--   _G.__SCVisionNukeStart()  -> ON
--   _G.__SCVisionNukeStop()   -> OFF
--
-- Compatible with the original Minecraft-texture preservation hooks when
-- those functions/state exist. Otherwise it safely falls back to normal
-- optimization behavior.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService") -- retained from source integration
local LP = Players.LocalPlayer

-- Standalone replacement for the original script's local settings table.
-- Set _G.__SCVisionNukeSettings.avaPresetEnabled = true when an Ava Preset is active.
local NukeSettings = _G.__SCVisionNukeSettings or { avaPresetEnabled = false }
_G.__SCVisionNukeSettings = NukeSettings

_G.__SCVisionNukeOn = _G.__SCVisionNukeOn or false
_G.__SCVisionNukeConns = _G.__SCVisionNukeConns or {}
_G.__SCVisionNukeThreads = _G.__SCVisionNukeThreads or {}

-- Minimal state fallback so this extracted module can run by itself.
local NukeState = _G.VasperNukeState or {}
NukeState.minecraftTextureEnabled = NukeState.minecraftTextureEnabled == true
_G.VasperNukeState = NukeState

local function IsMinecraftTextureObject(obj)
    if _G.IsMinecraftTextureObject then
        local ok, result = pcall(_G.IsMinecraftTextureObject, obj)
        if ok then return result end
    end
    return obj and type(obj.Name) == "string"
        and obj.Name:sub(1, #"__MC_V5__") == "__MC_V5__"
end

local function IsMinecraftLightingObject(obj)
    if _G.IsMinecraftLightingObject then
        local ok, result = pcall(_G.IsMinecraftLightingObject, obj)
        if ok then return result end
    end
    return obj and (obj.Name == "__MC_V5_Sky" or obj.Name == "__MC_V5_Atmos")
end

local function RefreshMinecraftAfterNuke()
    if not NukeState.minecraftTextureEnabled then return end
    local create = _G.minecraftCreateSkyAndAtmosphere or minecraftCreateSkyAndAtmosphere
    local repair = _G.integrityRepair or integrityRepair
    local scanFn = _G.scan or scan

    task.spawn(function()
        for _ = 1, 5 do
            if not NukeState.minecraftTextureEnabled then return end
            pcall(function()
                if create then create() end
            end)
            pcall(function()
                if repair then repair() end
            end)
            pcall(function()
                if scanFn then scanFn() end
            end)
            task.wait(0.22)
        end
    end)
end

_G.__SCVisionNukeStart = function()
        if _G.__SCVisionNukeOn then
            RefreshMinecraftAfterNuke()
            return
        end
        _G.__SCVisionNukeOn=true
        local Lighting=game:GetService("Lighting")
        local MaterialService=game:GetService("MaterialService")
        local XMin,XMax=-560,-240
        local ClothingClasses={"Shirt","Pants","ShirtGraphic","Accessory","Hat","HairAccessory","FaceAccessory","NeckAccessory","ShoulderAccessory","FrontAccessory","BackAccessory","WaistAccessory"}
        local BASE_NAMES={"baseplate","spawnlocation","spawn location","spawn"}

        -- Objects created by Vyxro's Avatar Changer must survive Nuke Optimizer.
        -- Use an attribute marker so normal game accessories/clothes can still
        -- be optimized away. Descendants inherit protection via ancestor lookup.
        -- AVA PRESET / AVATAR CHANGER PROTECTION
        -- The preset uses _VxyroAvaPreset, while the Avatar Changer uses
        -- _VyxroAvatarChanger. Both markers must survive the nuke pass.
        local function IsVyxroAvatarObject(obj)
            local cur = obj
            while cur and cur ~= workspace do
                local marked = false
                pcall(function()
                    marked = cur:GetAttribute("_VyxroAvatarChanger") == true
                        or cur:GetAttribute("_VxyroAvaPreset") == true
                end)
                if marked then return true end
                cur = cur.Parent
            end
            return false
        end

        -- When Ava Preset is enabled, never optimize the local
        -- character through the global workspace scan. This is intentionally
        -- stronger than marker-only protection because HumanoidDescription
        -- may create Shirt/Pants/Accessory instances before the preset
        -- marker can be attached, which otherwise creates a race with Nuke.
        local function IsLocalAvaPresetObject(obj)
            if not obj or not LP.Character then return false end
            if NukeSettings.avaPresetEnabled ~= true then return false end
            local ok, inside = pcall(function() return obj:IsDescendantOf(LP.Character) end)
            return ok and inside == true
        end

        local function IsVyxroProtectedLighting(obj)
            if not obj then return false end
            if obj.Name == "VyxroMotionBlur" then return true end
            if type(obj.Name) == "string" and obj.Name:sub(1,10) == "VyxroVivid" then return true end
            local marked = false
            pcall(function() marked = obj:GetAttribute("_VyxroImportedVivid") == true end)
            return marked
        end

        -- Hard protection for every player's full character tree. This includes
        -- custom avatar bodies, accessories, clothing, face decals, mesh textures,
        -- and any descendants which are added while Nuke Optimizer is running.
        local function IsCharacterPart(obj)
            if not obj then return false end
            for _,plr in ipairs(Players:GetPlayers()) do
                local character = plr.Character
                if character then
                    if obj == character then return true end
                    local ok, inside = pcall(function()
                        return obj:IsDescendantOf(character)
                    end)
                    if ok and inside == true then return true end
                end
            end
            -- Covers avatar/custom-character models during the brief respawn window
            -- before Player.Character is assigned, plus character models spawned by
            -- avatar changers. Marked Avatar Changer trees are also protected below.
            local cur = obj
            while cur and cur ~= workspace do
                local isCharacterModel = false
                pcall(function()
                    isCharacterModel = cur:IsA("Model")
                        and cur:FindFirstChildOfClass("Humanoid") ~= nil
                end)
                if isCharacterModel then return true end
                cur = cur.Parent
            end
            return false
        end

        local function SafeDestroy(obj)
            if IsCharacterPart(obj) then return end
            if IsLocalAvaPresetObject(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            if obj.Name=="Overhead" then return end
            pcall(function() obj:Destroy() end)
        end
        local function IsClothing(obj)
            for _,c in ipairs(ClothingClasses) do if obj:IsA(c) then return true end end
            return false
        end
        local function IsOutOfRange(obj)
            if obj:IsA("BasePart") then local x=obj.Position.X; return x<XMin or x>XMax end
            return false
        end
        local function IsBase(obj)
            if not obj:IsA("BasePart") then return false end
            local nl=obj.Name:lower()
            for _,n in ipairs(BASE_NAMES) do if nl:find(n,1,true) then return true end end
            return false
        end
        local function IsInBase(obj)
            local p=obj.Parent
            while p and p~=workspace do
                if IsBase(p) then return true end
                p=p.Parent
            end
            return false
        end
        local function MakeTransparent(obj)
            if IsCharacterPart(obj) then return end
            if IsMinecraftTextureObject(obj) then return end
            pcall(function()
                if IsBase(obj) and not IsCharacterPart(obj) then
                    obj.Transparency=1; obj.CastShadow=false
                end
            end)
        end
        local function StripObject(obj)
            if IsCharacterPart(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            pcall(function()
                if obj:IsA("Texture") or obj:IsA("Decal") or obj:IsA("SpecialMesh") then
                    SafeDestroy(obj)
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
                    pcall(function() obj.Enabled=false end)
                    SafeDestroy(obj)
                elseif obj:IsA("SurfaceAppearance") then
                    SafeDestroy(obj)
                elseif obj:IsA("BasePart") then
                    obj.CastShadow=false
                    -- Minecraft Texture owns the visual material/color behavior while active.
                    if not NukeState.minecraftTextureEnabled then
                        obj.Material=Enum.Material.Plastic
                        obj.MaterialVariant=""
                        obj.Reflectance=0
                    end
                end
            end)
        end
        local function CleanObject(obj)
            if IsCharacterPart(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            pcall(function()
                if obj:IsA("SurfaceAppearance") then
                    -- Do not fight active Minecraft Texture on MeshParts.
                    if NukeState.minecraftTextureEnabled then return end
                    SafeDestroy(obj)
                elseif obj:IsA("Decal") or obj:IsA("Texture") then
                    if not (obj.Name=="face" and obj.Parent and obj.Parent.Name=="Head") then SafeDestroy(obj) end
                elseif obj:IsA("SpecialMesh") then
                    obj.TextureId=""
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then
                    SafeDestroy(obj)
                elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
                    SafeDestroy(obj)
                elseif obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") or obj:IsA("Explosion") then
                    SafeDestroy(obj)
                elseif obj:IsA("Animation") or obj:IsA("AnimationController") then
                    SafeDestroy(obj)
                elseif obj:IsA("BasePart") then
                    obj.CastShadow=false
                    if not NukeState.minecraftTextureEnabled then
                        obj.Material=Enum.Material.Plastic
                        obj.MaterialVariant=""
                        obj.Reflectance=0
                    end
                end
            end)
        end
        local function ApplyGreySky()
            pcall(function()
                if NukeState.minecraftTextureEnabled then
                    minecraftCreateSkyAndAtmosphere()
                    return
                end
                for _,obj in ipairs(Lighting:GetChildren()) do
                    if obj:IsA("Sky") then obj:Destroy() end
                end
                local sky=Instance.new("Sky")
                sky.SkyboxBk=""; sky.SkyboxDn=""; sky.SkyboxFt=""; sky.SkyboxLf=""; sky.SkyboxRt=""; sky.SkyboxUp=""
                sky.CelestialBodiesShown=false
                sky.Name="_VezyNukeSky"
                sky.Parent=Lighting
            end)
        end
        local function OptimizeLighting()
            Lighting.GlobalShadows=false
            Lighting.FogEnd=9e9
            Lighting.FogStart=9e9
            Lighting.EnvironmentDiffuseScale=0
            Lighting.EnvironmentSpecularScale=0
            Lighting.Brightness=1.5
            Lighting.Ambient=Color3.fromRGB(60, 60, 60)
            for _,v in ipairs(Lighting:GetChildren()) do
                local preserve = (NukeState.minecraftTextureEnabled and IsMinecraftLightingObject(v)) or IsVyxroProtectedLighting(v)
                if not preserve and (v:IsA("BloomEffect") or v:IsA("BlurEffect") or v:IsA("ColorCorrectionEffect") or v:IsA("SunRaysEffect") or v:IsA("DepthOfFieldEffect") or v:IsA("Atmosphere") or v:IsA("Clouds")) then
                    v:Destroy()
                end
            end
            ApplyGreySky()
        end
        local function ApplyTerrain()
            pcall(function() local T=workspace.Terrain; T.Decoration=false; T.WaterWaveSize=0; T.WaterWaveSpeed=0; T.WaterReflectance=0; T.WaterTransparency=1 end)
        end
        local function OptimizeCharacter(char)
            if not char then return end
            -- Do not optimize player characters at all: avatars and custom appearances
            -- must remain intact, regardless of whether their preset marker has loaded.
            if IsCharacterPart(char) then return end
            -- Local Ava Preset character is completely excluded from Nuke.
            if char == LP.Character and NukeSettings.avaPresetEnabled == true then return end
            if IsVyxroAvatarObject(char) then return end
            task.spawn(function()
                task.wait(0.3)
                if not _G.__SCVisionNukeOn then return end
                for i,obj in ipairs(char:GetDescendants()) do
                    if not _G.__SCVisionNukeOn then return end
                    if IsVyxroAvatarObject(obj) then
                    elseif IsMinecraftTextureObject(obj) then
                    elseif IsClothing(obj) then SafeDestroy(obj)
                    else CleanObject(obj) end
                    if i % 100 == 0 then task.wait() end
                end
                RefreshMinecraftAfterNuke()
            end)
        end
        pcall(function() settings().Rendering.QualityLevel=Enum.QualityLevel.Level01; settings().Rendering.MeshPartDetailLevel=Enum.MeshPartDetailLevel.Level01 end)
        pcall(function() if setfpscap then setfpscap(60) end end)

        table.insert(_G.__SCVisionNukeThreads,task.spawn(function()
            if not game:IsLoaded() then game.Loaded:Wait() end
            OptimizeLighting(); ApplyTerrain()
            if NukeState.minecraftTextureEnabled then pcall(minecraftCreateSkyAndAtmosphere) end
            for i,obj in ipairs(workspace:GetDescendants()) do
                if not _G.__SCVisionNukeOn then return end
                -- IMPORTANT: check local preset protection BEFORE IsClothing.
                -- Otherwise Shirt/Pants/Accessory are destroyed by the generic
                -- clothing branch before character protection can run.
                if IsCharacterPart(obj) or IsLocalAvaPresetObject(obj) or IsVyxroAvatarObject(obj) then
                elseif IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then
                elseif IsBase(obj) then MakeTransparent(obj)
                elseif IsClothing(obj) then SafeDestroy(obj)
                elseif IsInBase(obj) then
                elseif IsOutOfRange(obj) then SafeDestroy(obj)
                else CleanObject(obj); StripObject(obj) end
                if i % 120 == 0 then task.wait() end
            end
            if NukeState.minecraftTextureEnabled then RefreshMinecraftAfterNuke() end
        end))

        table.insert(_G.__SCVisionNukeConns,workspace.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            task.defer(function()
                if not _G.__SCVisionNukeOn then return end
                if IsCharacterPart(obj) then return end
                if IsLocalAvaPresetObject(obj) then return end
                if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
                if NukeSettings.avaPresetEnabled == true and LP.Character and obj:IsDescendantOf(LP.Character) then return end
                if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
                if IsBase(obj) then MakeTransparent(obj); return end
                if IsClothing(obj) then SafeDestroy(obj)
                elseif IsInBase(obj) then
                elseif IsCharacterPart(obj) then
                elseif IsOutOfRange(obj) then SafeDestroy(obj)
                else CleanObject(obj); StripObject(obj) end
            end)
        end))

        table.insert(_G.__SCVisionNukeConns,Lighting.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            if IsVyxroProtectedLighting(obj) then return end
            if NukeState.minecraftTextureEnabled and IsMinecraftLightingObject(obj) then return end
            if obj:IsA("Atmosphere") or obj:IsA("Clouds") or obj:IsA("PostEffect") then SafeDestroy(obj) end
        end))

        table.insert(_G.__SCVisionNukeConns,MaterialService.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            SafeDestroy(obj)
        end))

        for _,plr in ipairs(Players:GetPlayers()) do
            OptimizeCharacter(plr.Character)
            table.insert(_G.__SCVisionNukeConns,plr.CharacterAdded:Connect(OptimizeCharacter))
        end
        table.insert(_G.__SCVisionNukeConns,Players.PlayerAdded:Connect(function(plr)
            table.insert(_G.__SCVisionNukeConns,plr.CharacterAdded:Connect(OptimizeCharacter))
        end))
        table.insert(_G.__SCVisionNukeThreads,task.spawn(function()
            while _G.__SCVisionNukeOn do
                task.wait(15)
                pcall(function() collectgarbage("collect") end)
                if NukeState.minecraftTextureEnabled then RefreshMinecraftAfterNuke() end
            end
        end))
        RefreshMinecraftAfterNuke()
    end
    
_G.__SCVisionNukeStop = function()
    _G.__SCVisionNukeOn = false

    for _, c in ipairs(_G.__SCVisionNukeConns) do
        pcall(function() c:Disconnect() end)
    end
    _G.__SCVisionNukeConns = {}
    _G.__SCVisionNukeThreads = {}
end

-- Optional convenience toggle.
_G.__SCVisionNukeToggle = function(enabled)
    if enabled then
        _G.__SCVisionNukeStart()
    else
        _G.__SCVisionNukeStop()
    end
end
end)()

S.startNukeOptimizer = function()
    local startFn = _G.__SCVisionNukeStart
    if type(startFn) == "function" then
        return startFn()
    end
end
S.stopNukeOptimizer = function()
    local stopFn = _G.__SCVisionNukeStop
    if type(stopFn) == "function" then
        return stopFn()
    end
end

local function buildMainTab(pages)
    mkSection("Main", pages, "Aimbot")
    local batVis, _ = mkToggle("Main", pages, "Bat Aimbot", S.KB.AutoBat.kb, S.batAimbotEnabled, function(on)
        if on then
            if type(S._stopMobileAimbotModes) == "function" then pcall(S._stopMobileAimbotModes, "AutoBat") end
            if S.autoLeftEnabled then S.autoLeftEnabled=false; if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end; stopAutoLeft() end
            if S.autoRightEnabled then S.autoRightEnabled=false; if S.autoRightSetVisual then S.autoRightSetVisual(false) end; stopAutoRight() end
        end
        setBatAimbot(on); updateFloatingButtons()
    end, function(k,isGp)
        if isGp then S.KB.AutoBat.gp=k; S.KB.AutoBat.kb=nil
        else S.KB.AutoBat.kb=k; S.KB.AutoBat.gp=nil end; saveConfig()
    end)
    S.batAimbotSetVisual = batVis
    mkSection("Main", pages, "Counters")
    S.setBatCounterVisual, _ = mkToggle("Main", pages, "Bat Counter", nil, S.batCounterEnabled, function(on)
        S.batCounterEnabled = on
        if on then startBatCounter() else stopBatCounter() end
        saveConfig()
    end, nil)
    S.setBatCounterV2Visual, _ = mkToggle("Main", pages, "Bat Counter V2", nil, S.batCounterV2Enabled, function(on)
        S.batCounterV2Enabled = on
        if on then startBatCounterV2() else stopBatCounterV2() end
        saveConfig()
    end, nil)
    S.setMedusaVisual, _ = mkToggle("Main", pages, "Medusa Counter", nil, S.medusaCounterEnabled, function(on)
        S.medusaCounterEnabled=on
        if on then setupMedusaCounter(LP.Character) else stopMedusaCounter() end; saveConfig()
    end, nil)
    mkSection("Main", pages, "Bat Settings")
    do
        local card = mkCard("Main", pages, 40)
