        S.tpBatModeSelectorLabel.TextTruncate = Enum.TextTruncate.AtEnd
        S.tpBatModeSelectorLabel.ZIndex = 9
        local right = makeTpBatModeButton(">", 144)

        local modeOptions = {TP_BAT_MODE_VISION, TP_BAT_MODE_ZERO, TP_BAT_MODE_ORBIT}
        local function changeTpBatMode(direction)
            local index = 1
            for i, mode in ipairs(modeOptions) do
                if mode == S.tpBatMode then index = i; break end
            end
            index = index + direction
            if index < 1 then index = #modeOptions end
            if index > #modeOptions then index = 1 end

            local wasEnabled = S.tpBatEnabled == true
            S.tpBatMode = modeOptions[index]
            S.tpBatModeSelectorLabel.Text = S.tpBatMode
            if wasEnabled then
                -- setTpBat dispatches the new selected implementation after safely
                -- stopping/disconnecting the previous one.
                setTpBat(true)
            end
            saveConfig()
        end
        left.MouseButton1Click:Connect(function() changeTpBatMode(-1) end)
        right.MouseButton1Click:Connect(function() changeTpBatMode(1) end)
    end
