    -- Custom crosshair controls; the overlay remains behind the main dashboard
    -- and appears again when the dashboard is closed.
    mkSection("Main", pages, "Crosshair")
    local function setCrosshairEnabledState(on, persist)
        S.crosshairEnabled = on == true
        if type(S.renderCrosshair) == "function" then
            local renderOk, renderErr = pcall(S.renderCrosshair)
            if not renderOk then warn("[XYPHER] Crosshair render gagal: " .. tostring(renderErr)) end
        end
        -- Keep the visual switch synchronized when state is restored by config or code.
        if type(S.setCrosshairEnabledVisual) == "function" then
            pcall(S.setCrosshairEnabledVisual, S.crosshairEnabled)
        end
        if persist ~= false then saveConfig() end
        return S.crosshairEnabled
    end
    S._setCrosshairEnabled = setCrosshairEnabledState
    S.setCrosshairEnabledVisual, _ = mkToggle("Main", pages, "Custom Crosshair", nil, S.crosshairEnabled == true, function(on)
        setCrosshairEnabledState(on, true)
    end, nil)

