    -- Exclusive background choices for every floating mobile button.
    -- Open Background controls the visibility of all image choice rows; the
    -- thumbnail preview sits beside each matching toggle.
    mkSection("Main", pages, "Mobile Button Background")
    S.stealPhotoToggleSetters = {}
    local backgroundOptionCards = {}

    local function setBackgroundOptionRowsVisible(visible)
        S.openBackgroundOptions = visible == true
        for _, optionCard in ipairs(backgroundOptionCards) do
            if optionCard and optionCard.Parent then
                optionCard.Visible = S.openBackgroundOptions
            end
        end
    end
    -- Expose the local row controller for Reset Config, which is built in a
    -- separate function scope from the Main tab.
    S.setBackgroundOptionsVisible = setBackgroundOptionRowsVisible

    local function applyStealPhotoChoice(assetId)
        local validId = nil
        for _, optionId in ipairs(STEAL_PHOTO_OPTIONS) do
            if assetId == optionId then validId = optionId; break end
        end
        S.stealPhotoAssetId = validId
        setStealPhotoImage(validId)
        for optionId, setter in pairs(S.stealPhotoToggleSetters or {}) do
            if type(setter) == "function" then pcall(setter, optionId == validId) end
        end
        saveConfig()
    end

    S.setOpenBackgroundVisual, _ = mkToggle("Main", pages, "Open Background", nil, S.openBackgroundOptions ~= false, function(on)
        setBackgroundOptionRowsVisible(on)
        saveConfig()
    end, nil)

    for photoIndex, photoId in ipairs(STEAL_PHOTO_OPTIONS) do
        local photoSetter, _, photoCard = mkToggle("Main", pages, "Background " .. tostring(photoIndex), nil, S.stealPhotoAssetId == photoId, function(on)
            if on then
                applyStealPhotoChoice(photoId)
            elseif S.stealPhotoAssetId == photoId then
                applyStealPhotoChoice(nil)
            end
        end, nil, photoId)
        S.stealPhotoToggleSetters[photoId] = photoSetter
        if photoCard then
            table.insert(backgroundOptionCards, photoCard)
            photoCard.Visible = S.openBackgroundOptions ~= false
        end
    end

    mkSection("Main", pages, "Mobile Buttons")
    do
        local card = mkCard("Main", pages, 86)

        local lbl = Instance.new("TextLabel", card)
