            tw:Play(); pcall(function() tw.Completed:Wait() end)
            if not hSepGlow.Parent then break end
            local tw2 = TS_G:Create(hSepGlow, TweenInfo.new(1.15, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {BackgroundTransparency = 0.92})
            tw2:Play(); pcall(function() tw2.Completed:Wait() end)
        end
    end)
