    local function makePanel(parent, name, position, size, background, radius, z)
        local frame = Instance.new("Frame")
        frame.Name = name
        frame.Position = position
        frame.Size = size
        frame.BackgroundColor3 = background or C_CARD
        frame.BackgroundTransparency = 0.04
        frame.BorderSizePixel = 0
        frame.ZIndex = z or 10
        frame.Parent = parent
        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, radius or 13)
        local stroke = Instance.new("UIStroke", frame)
        stroke.Color = C_BORDER
        stroke.Thickness = 1
        stroke.Transparency = 0.16
        return frame, stroke
    end

    local function makeLabel(parent, name, text, position, size, textSize, color, font, z, xAlign)
        local label = Instance.new("TextLabel")
        label.Name = name
        label.Position = position
        label.Size = size
        label.BackgroundTransparency = 1
        label.BorderSizePixel = 0
        label.Text = text
        label.TextColor3 = color or C_WHITE
        label.Font = font or Enum.Font.Gotham
        label.TextSize = textSize or 12
        label.TextXAlignment = xAlign or Enum.TextXAlignment.Left
        label.TextYAlignment = Enum.TextYAlignment.Center
        label.ZIndex = z or 12
        label.Active = false
        label.Selectable = false
        label.Parent = parent
        return label
    end

