    local themeCard, themeStroke = makePanel(rightRail, "XypherThemeCard", UDim2.fromOffset(8, 216), UDim2.new(1, -16, 0, 258), Color3.fromRGB(9, 6, 21), 13, 9)
    themeCard.BackgroundTransparency = 0.56
