    for _, savedTheme in ipairs(themeDefs) do
        if savedTheme.name == S.uiThemeName then
            activeThemeDef = savedTheme
            break
        end
    end
    local themeSwatches = {}

    -- The selected menu filters already-built controls by heading; callbacks remain unchanged.
    local sectionFilters = {
        ["Move"] = {
            ["Speed Values"]=true, ["Modes"]=true, ["Auto Path"]=true,
            ["Steal"]=true, ["Spin Settings"]=true, ["Move Actions"]=true,
        },
        ["Combat"] = {
            ["Aimbot"]=true, ["Counters"]=true, ["Bat Settings"]=true,
            ["Aimbot Speed Controls"]=true,
        },
        ["Visual"] = {
            ["Display Mode"]=true, ["Visuals"]=true, ["Crosshair"]=true,
            ["Mobile Button Background"]=true, ["Mobile Buttons"]=true,
            ["Steal Bar Size"]=true, ["Background"]=true,
        },
        ["More"] = {
